window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[10]=[{"t": "h", "l": 0, "s": "Лекц 10. Тоноглолын онлайн хяналт ба оношлогоо", "h": "<b>Лекц 10. Тоноглолын онлайн хяналт ба оношлогоо</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Засвар үйлчилгээний стратеги (гэмтлийн дараах, хугацаат, төлөвт суурилсан, найдвартай ажиллагаанд төвлөрсөн, эрсдэлд суурилсан)-ийг харьцуулах; хүчний трансформаторын тосонд уусмал хийн шинжилгээ (DGA)-г IEC 60599-ийн харьцааны арга, Дювалын гурвалжин, Рожерсийн аргаар тайлбарлах; тос-цаасны чийг, оруулгын багтаамж ба tanδ, дулааны горим, хөгшрөлтийн хурд, OLTC-ийн хяналтыг ойлгох; хэсэгчилсэн цэнэгийн физик, хэмжих аргууд (IEC 60270, UHF, акустик, HFCT, TEV), PRPD дүрсийг таних; КРУЭ/GIS-ийн SF6 нягтын хяналт, таслуурын ороомгийн гүйдэл, контактын элэгдэл, хэт хүчдэл хязгаарлагчийн алдагдлын гүйдэл, инфра улаан термографийн шалгуурыг хэрэглэх; IEC 61850-д суурилсан онлайн хяналтын архитектур, эрүүл мэндийн индекс ба эрсдэлийн матрицаар тоноглолыг эрэмбэлэх.", "h": "<b>Лекцийн зорилго.</b> Засвар үйлчилгээний стратеги (гэмтлийн дараах, хугацаат, төлөвт суурилсан, найдвартай ажиллагаанд төвлөрсөн, эрсдэлд суурилсан)-ийг харьцуулах; хүчний трансформаторын тосонд уусмал хийн шинжилгээ (DGA)-г IEC 60599-ийн харьцааны арга, Дювалын гурвалжин, Рожерсийн аргаар тайлбарлах; тос-цаасны чийг, оруулгын багтаамж ба tanδ, дулааны горим, хөгшрөлтийн хурд, OLTC-ийн хяналтыг ойлгох; хэсэгчилсэн цэнэгийн физик, хэмжих аргууд (IEC 60270, UHF, акустик, HFCT, TEV), PRPD дүрсийг таних; КРУЭ/GIS-ийн SF6 нягтын хяналт, таслуурын ороомгийн гүйдэл, контактын элэгдэл, хэт хүчдэл хязгаарлагчийн алдагдлын гүйдэл, инфра улаан термографийн шалгуурыг хэрэглэх; IEC 61850-д суурилсан онлайн хяналтын архитектур, эрүүл мэндийн индекс ба эрсдэлийн матрицаар тоноглолыг эрэмбэлэх.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: төлөвт суурилсан засвар (CBM), RCM, P–F интервал, DGA, IEC 60599, Дювалын гурвалжин, Рожерсийн харьцаа, харьцангуй ханалт, оруулгын C1 ба tanδ, халуун цэг, хөгшрөлтийн хурд, OLTC, хэсэгчилсэн цэнэг, илэрхий цэнэг, UHF, PRPD, SF6 нягт, ороомгийн гүйдэл, I²t элэгдэл, гуравдугаар гармоник, термографи, эрүүл мэндийн индекс, эрсдэлийн матриц.", "h": "<b>Түлхүүр үг:</b> төлөвт суурилсан засвар (CBM), RCM, P–F интервал, DGA, IEC 60599, Дювалын гурвалжин, Рожерсийн харьцаа, харьцангуй ханалт, оруулгын C1 ба tanδ, халуун цэг, хөгшрөлтийн хурд, OLTC, хэсэгчилсэн цэнэг, илэрхий цэнэг, UHF, PRPD, SF6 нягт, ороомгийн гүйдэл, I²t элэгдэл, гуравдугаар гармоник, термографи, эрүүл мэндийн индекс, эрсдэлийн матриц.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. Засвар\nүйлчилгээний стратеги ба гэмтлийн статистик", "h": "1. Засвар\nүйлчилгээний стратеги ба гэмтлийн статистик"}, {"t": "h", "l": 2, "s": "1.1. Яагаад онлайн хяналт\nхэрэгтэй вэ", "h": "1.1. Яагаад онлайн хяналт\nхэрэгтэй вэ"}, {"t": "p", "s": "Дэд станцын тоноглол — хүчний трансформатор, таслуур, КРУЭ/GIS, хэмжих трансформатор, хэт хүчдэл хязгаарлагч — нь 30–50 жил ажиллах зориулалттай, нэг бүрийн өртөг нь хэдэн зуун мянгаас хэдэн сая ам.доллар хүрдэг хөрөнгө юм. Монголын 110 ба 220 кВ-ын трансформаторын нэлээд хэсэг 1970–1980-аад онд суурилагдсан тул аль тоноглол хамгийн өндөр эрсдэлтэйг тоон үндэслэлтэй тодорхойлох шаардлага гарч байна. Онлайн хяналт ба оношлогоо нь энэ асуудлын технологийн хариулт юм.", "h": "Дэд станцын тоноглол — хүчний трансформатор, таслуур, КРУЭ/GIS, хэмжих трансформатор, хэт хүчдэл хязгаарлагч — нь 30–50 жил ажиллах зориулалттай, нэг бүрийн өртөг нь хэдэн зуун мянгаас хэдэн сая ам.доллар хүрдэг хөрөнгө юм. Монголын 110 ба 220 кВ-ын трансформаторын нэлээд хэсэг 1970–1980-аад онд суурилагдсан тул аль тоноглол хамгийн өндөр эрсдэлтэйг тоон үндэслэлтэй тодорхойлох шаардлага гарч байна. Онлайн хяналт ба оношлогоо нь энэ асуудлын технологийн хариулт юм."}, {"t": "p", "s": "Онлайн хяналт гэдэг нь тоноглолыг ажиллагаанаас гаргалгүйгээр түүний төлөвийг тодорхойлох параметрүүдийг тасралтгүй хэмжиж, дүн шинжилгээ хийж, хэвийн бус чиг хандлагыг эрт илрүүлэх систем юм. Оношлогоо нь хэмжилтийн үр дүнгээр гэмтлийн төрөл, байрлал, ноцтой байдлыг тодорхойлох үйл явц бөгөөд онлайн ба офлайн (тоноглолыг салгаж хийх) туршилтыг хослуулдаг.", "h": "Онлайн хяналт гэдэг нь тоноглолыг ажиллагаанаас гаргалгүйгээр түүний төлөвийг тодорхойлох параметрүүдийг тасралтгүй хэмжиж, дүн шинжилгээ хийж, хэвийн бус чиг хандлагыг эрт илрүүлэх систем юм. <b>Оношлогоо</b> нь хэмжилтийн үр дүнгээр гэмтлийн төрөл, байрлал, ноцтой байдлыг тодорхойлох үйл явц бөгөөд онлайн ба офлайн (тоноглолыг салгаж хийх) туршилтыг хослуулдаг."}, {"t": "h", "l": 2, "s": "1.2. Засвар үйлчилгээний\nстратеги", "h": "1.2. Засвар үйлчилгээний\nстратеги"}, {"t": "p", "s": "Засвар үйлчилгээний стратегийн хөгжлийг таван үе шатаар ялгаж болно (Хүснэгт 10.1).", "h": "Засвар үйлчилгээний стратегийн хөгжлийг таван үе шатаар ялгаж болно (Хүснэгт 10.1)."}, {"t": "p", "s": "Гэмтлийн дараах (засварлах) засвар (corrective, run-to-failure) — тоноглол гэмтсэний дараа засна. Хямд тоноглолд хүлээн зөвшөөрөгдөх боловч трансформаторт аваарын хохирол, гал түймрийн эрсдэл өндөр.", "h": "• <b>Гэмтлийн дараах (засварлах) засвар</b> (corrective, run-to-failure) — тоноглол гэмтсэний дараа засна. Хямд тоноглолд хүлээн зөвшөөрөгдөх боловч трансформаторт аваарын хохирол, гал түймрийн эрсдэл өндөр."}, {"t": "p", "s": "Хугацаат (урьдчилан сэргийлэх) засвар (time-based maintenance, TBM) — үйлдвэрлэгчийн зөвлөмж эсвэл дүрмээр тогтоосон хугацаанд (жишээ нь таслуурыг 6–8 жил тутам, трансформаторын их засварыг 12 жил тутам) төлөвөөс үл хамааран засна. Хуучин «ППР» систем ийм зарчимтай бөгөөд Монголд одоо ч хэрэглэгддэг. Хэвийн тоноглолыг шаардлагагүй задлах нь өөрөө гэмтлийн эх үүсвэр болдог, харин хоёр засварын хооронд үүссэн гэмтлийг илрүүлдэггүй.", "h": "• <b>Хугацаат (урьдчилан сэргийлэх) засвар</b> (time-based maintenance, TBM) — үйлдвэрлэгчийн зөвлөмж эсвэл дүрмээр тогтоосон хугацаанд (жишээ нь таслуурыг 6–8 жил тутам, трансформаторын их засварыг 12 жил тутам) төлөвөөс үл хамааран засна. Хуучин «ППР» систем ийм зарчимтай бөгөөд Монголд одоо ч хэрэглэгддэг. Хэвийн тоноглолыг шаардлагагүй задлах нь өөрөө гэмтлийн эх үүсвэр болдог, харин хоёр засварын хооронд үүссэн гэмтлийг илрүүлдэггүй."}, {"t": "p", "s": "Төлөвт суурилсан засвар (condition-based maintenance, CBM) — тоноглолын бодит төлөвийг хэмжиж, шаардлагатай үед л засна. Онлайн хяналт нь CBM-ийн техникийн суурь юм.", "h": "• <b>Төлөвт суурилсан засвар</b> (condition-based maintenance, CBM) — тоноглолын бодит төлөвийг хэмжиж, шаардлагатай үед л засна. Онлайн хяналт нь CBM-ийн техникийн суурь юм."}, {"t": "p", "s": "Найдвартай ажиллагаанд төвлөрсөн засвар (reliability-centred maintenance, RCM) — тоноглолын функц, гэмтлийн хэлбэр ба тэдгээрийн үр дагавар (FMEA/FMECA) дээр үндэслэн тоноглол бүрд тохирох стратегийг (TBM, CBM эсвэл гэмтлийн дараах) сонгоно.", "h": "• <b>Найдвартай ажиллагаанд төвлөрсөн засвар</b> (reliability-centred maintenance, RCM) — тоноглолын функц, гэмтлийн хэлбэр ба тэдгээрийн үр дагавар (FMEA/FMECA) дээр үндэслэн тоноглол бүрд тохирох стратегийг (TBM, CBM эсвэл гэмтлийн дараах) сонгоно."}, {"t": "p", "s": "Эрсдэлд суурилсан засвар (risk-based maintenance, RBM) — гэмтлийн магадлал ба үр дагаврын үржвэр болох эрсдэлээр тоноглолыг эрэмбэлж, засвар, шинэчлэлийн хөрөнгийг эрсдэл хамгийн их бууруулах газарт зарцуулна. ISO 55000 цувралын хөрөнгийн удирдлагын зарчимтай нийцдэг.", "h": "• <b>Эрсдэлд суурилсан засвар</b> (risk-based maintenance, RBM) — гэмтлийн магадлал ба үр дагаврын үржвэр болох эрсдэлээр тоноглолыг эрэмбэлж, засвар, шинэчлэлийн хөрөнгийг эрсдэл хамгийн их бууруулах газарт зарцуулна. ISO 55000 цувралын хөрөнгийн удирдлагын зарчимтай нийцдэг."}, {"t": "cap", "s": "Хүснэгт 10.1. Засвар үйлчилгээний стратегийн харьцуулалт", "h": "Хүснэгт 10.1. Засвар үйлчилгээний стратегийн харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Стратеги", "Шийдвэрийн үндэс", "Мэдээллийн хэрэгцээ", "Давуу тал", "Сул тал"], "rows": [["Гэмтлийн дараах", "Гэмтэл гарсан", "Бага", "Урьдчилсан зардалгүй", "Аваарын хохирол, тасралт их"], ["Хугацаат (TBM)", "Хуанлийн хугацаа, ажилласан тоо", "Бага", "Төлөвлөхөд хялбар", "Илүүдэл засвар, завсрын гэмтэл илрэхгүй"], ["Төлөвт суурилсан (CBM)", "Хэмжсэн төлөв, чиг хандлага", "Их (мэдрэгч, шинжилгээ)", "Эрт илрүүлэлт, засварын зардал бага", "Хяналтын системийн хөрөнгө, мэргэшил"], ["RCM", "Функц, гэмтлийн хэлбэр, үр дагавар", "Дунд–их", "Тоноглол бүрд оновчтой стратеги", "Шинжилгээ их хөдөлмөр шаардана"], ["Эрсдэлд суурилсан", "Магадлал × үр дагавар", "Их (HI, үр дагаврын загвар)", "Хөрөнгийг оновчтой хуваарилна", "Загварын тодорхой бус байдал"]]}, {"t": "p", "s": "Төлөвт суурилсан засварын үзэл санааг P–F муруй сайн харуулдаг (Зураг 10.1). Гэмтэл үүссэнээс хойш тоноглолын төлөв аажмаар муудаж, тодорхой агшинд (P цэг) хэмжилтээр илрэх боломжтой болно; цаашид функциональ гэмтэл (F цэг) хүртэлх хугацааг P–F интервал гэнэ. Хяналтын давтамж P–F интервалаас хангалттай бага байж гэмтлийг F-ээс өмнө барих ёстой. P–F интервал нь ороомгийн дулааны гэмтэлд хэдэн сараас жил, оруулгын цохилтод хэдэн долоо хоног, бүр цаг байж болно.", "h": "Төлөвт суурилсан засварын үзэл санааг <b>P–F муруй</b> сайн харуулдаг (Зураг 10.1). Гэмтэл үүссэнээс хойш тоноглолын төлөв аажмаар муудаж, тодорхой агшинд (P цэг) хэмжилтээр илрэх боломжтой болно; цаашид функциональ гэмтэл (F цэг) хүртэлх хугацааг <b>P–F интервал</b> гэнэ. Хяналтын давтамж P–F интервалаас хангалттай бага байж гэмтлийг F-ээс өмнө барих ёстой. P–F интервал нь ороомгийн дулааны гэмтэлд хэдэн сараас жил, оруулгын цохилтод хэдэн долоо хоног, бүр цаг байж болно."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.1. P–F муруй: гэмтлийн хөгжил, хугацаат үзлэг ба онлайн хяналт", "h": "Зураг 10.1. P–F муруй: гэмтлийн хөгжил, хугацаат үзлэг ба онлайн хяналт"}, {"t": "h", "l": 2, "s": "1.3. Гэмтлийн статистик", "h": "1.3. Гэмтлийн статистик"}, {"t": "p", "s": "Хяналтын системийг хаана төвлөрүүлэхийг гэмтлийн статистик тодорхойлно. CIGRE-ийн трансформаторын найдвартай ажиллагааны судалгаа (TB 642, 2015)-гаар 100 кВ-оос дээш хүчдэлийн трансформаторын томоохон гэмтлийн жилийн давтамж дунджаар 0.5–1 % орчим байна. Гэмтлийн байрлалын ойролцоо тархалтыг Хүснэгт 10.2-т үзүүлэв. Ороомог, шилжүүлэгч (OLTC), оруулга гурав нийлээд гэмтлийн 80 орчим хувийг эзэлдэг тул хяналтын үндсэн хэрэгсэл — DGA, оруулгын хяналт, OLTC-ийн хяналт — эдгээр хэсэгт чиглэнэ. Оруулгын гэмтэл ихэвчлэн сав хагарах, гал авалцахад хүргэдэг.", "h": "Хяналтын системийг хаана төвлөрүүлэхийг гэмтлийн статистик тодорхойлно. CIGRE-ийн трансформаторын найдвартай ажиллагааны судалгаа (TB 642, 2015)-гаар 100 кВ-оос дээш хүчдэлийн трансформаторын томоохон гэмтлийн жилийн давтамж дунджаар 0.5–1 % орчим байна. Гэмтлийн байрлалын ойролцоо тархалтыг Хүснэгт 10.2-т үзүүлэв. Ороомог, шилжүүлэгч (OLTC), оруулга гурав нийлээд гэмтлийн 80 орчим хувийг эзэлдэг тул хяналтын үндсэн хэрэгсэл — DGA, оруулгын хяналт, OLTC-ийн хяналт — эдгээр хэсэгт чиглэнэ. Оруулгын гэмтэл ихэвчлэн сав хагарах, гал авалцахад хүргэдэг."}, {"t": "p", "s": "Таслуурын хувьд CIGRE-ийн олон улсын судалгаагаар (TB 510) томоохон гэмтлийн дийлэнх нь ажиллуулах механизм ба удирдлагын хэлхээтэй холбоотой бөгөөд «тушаалаар ажилласангүй» эсвэл «тушаалгүй ажиллав» хэлбэрээр илэрдэг; иймээс хяналтын гол объект нь ороомгийн гүйдэл, хөтлүүр, хугацааны параметр юм.", "h": "Таслуурын хувьд CIGRE-ийн олон улсын судалгаагаар (TB 510) томоохон гэмтлийн дийлэнх нь <b>ажиллуулах механизм ба удирдлагын хэлхээ</b>тэй холбоотой бөгөөд «тушаалаар ажилласангүй» эсвэл «тушаалгүй ажиллав» хэлбэрээр илэрдэг; иймээс хяналтын гол объект нь ороомгийн гүйдэл, хөтлүүр, хугацааны параметр юм."}, {"t": "cap", "s": "Хүснэгт 10.2. 100 кВ-оос дээш хүчдэлийн дэд станцын трансформаторын гэмтлийн байрлал (CIGRE TB 642-ийн ойролцоо утга)", "h": "Хүснэгт 10.2. 100 кВ-оос дээш хүчдэлийн дэд станцын трансформаторын гэмтлийн байрлал (CIGRE TB 642-ийн ойролцоо утга)"}, {"t": "tbl", "s": "", "head": ["Гэмтлийн байрлал", "Хувь, %", "Гол шалтгаан", "Илрүүлэх хэрэгсэл"], "rows": [["Ороомог", "35–45", "Тусгаарлагын хөгшрөлт, ТЗ-ийн динамик хүч, хэт халалт", "DGA, PD, FRA, халуун цэг"], ["Шилжүүлэгч (OLTC)", "25–30", "Контактын элэгдэл, хөтлүүр, механизм", "Хөтлүүрийн момент, ΔT, OLTC-ийн DGA"], ["Оруулга", "15–20", "Чийг, PD, конденсаторын давхаргын цоорол", "C1, tanδ, PD"], ["Гаргалгаа, холболт", "5–8", "Холбоосын хэт халалт", "DGA, термографи"], ["Соронзон хүрээ, сав, хөргөлт", "5–10", "Олон цэгийн газардуулга, насос, сэнс", "DGA, хүрээний газардуулгын гүйдэл"]]}, {"t": "p", "s": "Жишээ 10.1. Эрчим хүчний компани 60 ширхэг 110 кВ-ын трансформатортой. Томоохон гэмтлийн давтамж λ=0.6 %/жил, нэг гэмтлийн нийт хохирол (сэргээн засвар, тасралт, гал) C г=2.5 сая $. Онлайн хяналт (DGA, оруулга) гэмтлийн 60 %-ийг эрт илрүүлж, тэдгээрийн хохирлыг 0.4 сая $ хүртэл бууруулна. Хяналтын хөрөнгө оруулалт трансформатор бүрд 25 мянган $, жилийн ашиглалтын зардал 2 мянган $, i=8 %, T=15 жил. Хяналтын систем эдийн засгийн хувьд үр ашигтай юу?", "h": "<b>Жишээ 10.1.</b> Эрчим хүчний компани 60 ширхэг 110 кВ-ын трансформатортой. Томоохон гэмтлийн давтамж λ=0.6 %/жил, нэг гэмтлийн нийт хохирол (сэргээн засвар, тасралт, гал) C<sub>г</sub>=2.5 сая $. Онлайн хяналт (DGA, оруулга) гэмтлийн 60 %-ийг эрт илрүүлж, тэдгээрийн хохирлыг 0.4 сая $ хүртэл бууруулна. Хяналтын хөрөнгө оруулалт трансформатор бүрд 25 мянган $, жилийн ашиглалтын зардал 2 мянган $, i=8 %, T=15 жил. Хяналтын систем эдийн засгийн хувьд үр ашигтай юу?", "x": "ex"}, {"t": "p", "s": "Бодолт. Жилийн хүлээгдэх хохирол", "h": "<i>Бодолт.</i> Жилийн хүлээгдэх хохирол", "x": "ex"}, {"t": "eq", "s": "R=N λ C г (10.1)", "h": "R=N λ C<sub>г</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>N</mi><mspace width=\"0.167em\"></mspace><mi>λ</mi><mspace width=\"0.167em\"></mspace><msub><mi>C</mi><mi>г</mi></msub></mrow></semantics></math>", "n": "10.1", "x": "ex"}, {"t": "p", "s": "Хяналтгүй үед R 0=60⋅0.006⋅2.5=0.900 сая $/жил байна. Хяналттай үед гэмтлийн 40 % нь бүрэн хохиролтой, 60 % нь бага хохиролтой тул R 1=60⋅0.006⋅(0.4⋅2.5+0.6⋅0.4)=0.446 сая $/жил, жилийн ашиг ΔR=0.454 сая $.", "h": "Хяналтгүй үед R<sub>0</sub>=60⋅0.006⋅2.5=0.900 сая $/жил байна. Хяналттай үед гэмтлийн 40 % нь бүрэн хохиролтой, 60 % нь бага хохиролтой тул R<sub>1</sub>=60⋅0.006⋅(0.4⋅2.5+0.6⋅0.4)=0.446 сая $/жил, жилийн ашиг ΔR=0.454 сая $.", "x": "ex"}, {"t": "p", "s": "Хөрөнгө оруулалтыг жилийн тэнцүү төлбөр болгох коэффициент", "h": "Хөрөнгө оруулалтыг жилийн тэнцүү төлбөр болгох коэффициент", "x": "ex"}, {"t": "eq", "s": "CRF=(i (1+i)^T)/((1+i)^T−1) (10.2)", "h": "CRF=(i (1+i)<sup>T</sup>)/((1+i)<sup>T</sup>−1)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mi>R</mi><mi>F</mi><mo>=</mo><mfrac><mrow><mi>i</mi><mspace width=\"0.167em\"></mspace><msup><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mi>T</mi></msup></mrow><mrow><msup><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>1</mn><mo>+</mo><mi>i</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mi>T</mi></msup><mo>−</mo><mn>1</mn></mrow></mfrac></mrow></semantics></math>", "n": "10.2", "x": "ex"}, {"t": "p", "s": "(10.2)-оор CRF=0.1168 гарна. Жилийн нийт зардал нь хөрөнгө оруулалтын хэсэг 60⋅0.025⋅0.1168=0.175 сая $ ба ашиглалтын зардал 60⋅0.002=0.120 сая $-ийн нийлбэр буюу 0.295 сая $. Ашиг/зардлын харьцаа 0.454/0.295=1.54>1 тул хяналт үр ашигтай. Тасралтын нийгмийн хохирлыг тооцвол үр ашиг илүү өндөр.", "h": "(10.2)-оор CRF=0.1168 гарна. Жилийн нийт зардал нь хөрөнгө оруулалтын хэсэг 60⋅0.025⋅0.1168=0.175 сая $ ба ашиглалтын зардал 60⋅0.002=0.120 сая $-ийн нийлбэр буюу 0.295 сая $. Ашиг/зардлын харьцаа 0.454/0.295=1.54&gt;1 тул хяналт үр ашигтай. Тасралтын нийгмийн хохирлыг тооцвол үр ашиг илүү өндөр.", "x": "ex"}, {"t": "h", "l": 1, "s": "2. Хүчний трансформаторын\nхяналт", "h": "2. Хүчний трансформаторын\nхяналт"}, {"t": "p", "s": "Трансформаторын онлайн хяналтын ердийн бүрэлдэхүүнийг Зураг 10.2-т үзүүлэв. Орчин үеийн «ухаалаг трансформатор» (Лекц 4)-т эдгээр мэдрэгч үйлдвэрээс суурилагдаж ирдэг бол хуучин трансформаторт DGA анализатор, оруулгын мэдрэгч, шилэн кабелийн бус дулааны загварыг нэмж суурилуулдаг.", "h": "Трансформаторын онлайн хяналтын ердийн бүрэлдэхүүнийг Зураг 10.2-т үзүүлэв. Орчин үеийн «ухаалаг трансформатор» (Лекц 4)-т эдгээр мэдрэгч үйлдвэрээс суурилагдаж ирдэг бол хуучин трансформаторт DGA анализатор, оруулгын мэдрэгч, шилэн кабелийн бус дулааны загварыг нэмж суурилуулдаг."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.2. Хүчний трансформаторын онлайн хяналтын мэдрэгчийн байрлал", "h": "Зураг 10.2. Хүчний трансформаторын онлайн хяналтын мэдрэгчийн байрлал"}, {"t": "h", "l": 2, "s": "2.1. Тосонд уусмал хийн\nшинжилгээ (DGA)", "h": "2.1. Тосонд уусмал хийн\nшинжилгээ (DGA)"}, {"t": "h", "l": 2, "s": "2.1.1. Хий үүсэх механизм", "h": "2.1.1. Хий үүсэх механизм"}, {"t": "p", "s": "Эрдэс тос нь CH₃, CH₂, CH бүлгүүдийг C–C бондоор холбосон нүүрс-устөрөгчийн молекулаас тогтоно. Цахилгаан эсвэл дулааны энергийн нөлөөгөөр C–H ба C–C бонд тасарч, үүссэн чөлөөт радикалууд нийлж бага молекулт хий үүсгэнэ. Бонд таслах энерги ба хий үүсэх температур өөр өөр тул хийн бүрэлдэхүүн нь гэмтлийн энергийн «хурууны хээ» болдог:", "h": "Эрдэс тос нь CH₃, CH₂, CH бүлгүүдийг C–C бондоор холбосон нүүрс-устөрөгчийн молекулаас тогтоно. Цахилгаан эсвэл дулааны энергийн нөлөөгөөр C–H ба C–C бонд тасарч, үүссэн чөлөөт радикалууд нийлж бага молекулт хий үүсгэнэ. Бонд таслах энерги ба хий үүсэх температур өөр өөр тул хийн бүрэлдэхүүн нь гэмтлийн энергийн «хурууны хээ» болдог:"}, {"t": "p", "s": "Устөрөгч (H₂) — бага энергийн процесс, ялангуяа хэсэгчилсэн цэнэг (PD), мөн бүх гэмтэлд бага хэмжээгээр;", "h": "• <b>Устөрөгч (H₂)</b> — бага энергийн процесс, ялангуяа хэсэгчилсэн цэнэг (PD), мөн бүх гэмтэлд бага хэмжээгээр;"}, {"t": "p", "s": "Метан (CH₄), этан (C₂H₆) — бага температурын хэт халалт (150–300 °C);", "h": "• <b>Метан (CH₄), этан (C₂H₆)</b> — бага температурын хэт халалт (150–300 °C);"}, {"t": "p", "s": "Этилен (C₂H₄) — 300 °C-ээс дээш хэт халалт, температур өсөх тусам эзлэх хувь нь ихэснэ;", "h": "• <b>Этилен (C₂H₄)</b> — 300 °C-ээс дээш хэт халалт, температур өсөх тусам эзлэх хувь нь ихэснэ;"}, {"t": "p", "s": "Ацетилен (C₂H₂) — 700–1000 °C-ээс дээш, ихэвчлэн цахилгаан нум, их энергийн цэнэг; маш бага хэмжээ ч (хэдэн ppm) анхаарал татах дохио;", "h": "• <b>Ацетилен (C₂H₂)</b> — 700–1000 °C-ээс дээш, ихэвчлэн цахилгаан нум, их энергийн цэнэг; маш бага хэмжээ ч (хэдэн ppm) анхаарал татах дохио;"}, {"t": "p", "s": "CO ба CO₂ — целлюлоз (цаас, картон) задрах; CO₂/CO харьцаа 3-аас бага бол цаасны хэт халалтыг сэжиглэнэ.", "h": "• <b>CO ба CO₂</b> — целлюлоз (цаас, картон) задрах; CO₂/CO харьцаа 3-аас бага бол цаасны хэт халалтыг сэжиглэнэ."}, {"t": "cap", "s": "Хүснэгт 10.3. Гэмтлийн хий, тэдгээрийн эх үүсвэр ба ердийн агууламж (IEC 60599, 90 %-ийн ердийн утгын муж)", "h": "Хүснэгт 10.3. Гэмтлийн хий, тэдгээрийн эх үүсвэр ба ердийн агууламж (IEC 60599, 90 %-ийн ердийн утгын муж)"}, {"t": "tbl", "s": "", "head": ["Хий", "Голлох эх үүсвэр", "Ердийн утга, ppm (μл/л)"], "rows": [["H₂", "PD, тосны задрал, ус электролиз", "50–150"], ["CH₄", "Бага температурын халалт", "30–130"], ["C₂H₆", "Бага температурын халалт", "20–90"], ["C₂H₄", "&gt; 300 °C халалт", "60–280"], ["C₂H₂", "Нум, &gt; 700 °C халалт", "2–20 (OLTC-оос нэвчилтгүй)"], ["CO", "Цаасны задрал", "400–600"], ["CO₂", "Цаасны задрал, хөгшрөлт", "3800–14000"]]}, {"t": "p", "s": "Хүснэгт 10.3-ийн утга нь хязгаар биш, паркийн 90 %-д тохиолдох «ердийн» агууламж юм. Үнэмлэхүй утгаас гадна хий өсөх хурд (ppm/өдөр, ppm/жил) илүү чухал: жишээ нь C₂H₂ нь 5 ppm-д тогтвортой байвал хуучин үйл явдлын ул мөр байж болох ч, долоо хоногт 2–3 ppm-ээр өсвөл идэвхтэй нум байгааг илтгэнэ.", "h": "Хүснэгт 10.3-ийн утга нь хязгаар биш, паркийн 90 %-д тохиолдох «ердийн» агууламж юм. Үнэмлэхүй утгаас гадна <b>хий өсөх хурд</b> (ppm/өдөр, ppm/жил) илүү чухал: жишээ нь C₂H₂ нь 5 ppm-д тогтвортой байвал хуучин үйл явдлын ул мөр байж болох ч, долоо хоногт 2–3 ppm-ээр өсвөл идэвхтэй нум байгааг илтгэнэ."}, {"t": "h", "l": 2, "s": "2.1.2. Онлайн DGA анализатор", "h": "2.1.2. Онлайн DGA анализатор"}, {"t": "p", "s": "Онлайн DGA төхөөрөмж (Зураг 10.3) нь трансформаторын доод хавхлагаас тосыг насосоор эргэлдүүлж, хийг тосноос ялгаж (полимер мембран эсвэл «headspace» — тосны дээрх хийн зай), хийн агууламжийг хэмжиж, тосыг буцааж савд оруулна. Хэмжих технологи нь:", "h": "Онлайн DGA төхөөрөмж (Зураг 10.3) нь трансформаторын доод хавхлагаас тосыг насосоор эргэлдүүлж, хийг тосноос ялгаж (полимер мембран эсвэл «headspace» — тосны дээрх хийн зай), хийн агууламжийг хэмжиж, тосыг буцааж савд оруулна. Хэмжих технологи нь:"}, {"t": "p", "s": "хийн хроматограф — лабораторийн аргатай адил нарийвчлалтай, 7–9 хийг ялгана, тээвэрлэгч хий (гелий) ба тохируулгын хий шаарддаг;", "h": "• <b>хийн хроматограф</b> — лабораторийн аргатай адил нарийвчлалтай, 7–9 хийг ялгана, тээвэрлэгч хий (гелий) ба тохируулгын хий шаарддаг;"}, {"t": "p", "s": "фотоакустик спектроскопи (PAS) — хий шингээсэн хэт улаан туяаны энерги даралтын долгион үүсгэх зарчимтай, тээвэрлэгч хий шаардлагагүй, засвар бага;", "h": "• <b>фотоакустик спектроскопи (PAS)</b> — хий шингээсэн хэт улаан туяаны энерги даралтын долгион үүсгэх зарчимтай, тээвэрлэгч хий шаардлагагүй, засвар бага;"}, {"t": "p", "s": "нэг эсвэл хоёр хийн мэдрэгч — H₂ ба CO-г (заримдаа C₂H₂) электрохимийн эсвэл хагас дамжуулагч мэдрэгчээр хэмжинэ; хямд, «эрт сэрэмжлүүлэг»-ийн зориулалттай.", "h": "• <b>нэг эсвэл хоёр хийн мэдрэгч</b> — H₂ ба CO-г (заримдаа C₂H₂) электрохимийн эсвэл хагас дамжуулагч мэдрэгчээр хэмжинэ; хямд, «эрт сэрэмжлүүлэг»-ийн зориулалттай."}, {"t": "p", "s": "Монголын нөхцөлд анализаторыг халаалттай шүүгээнд байрлуулж, онлайн утгыг жилд 1–2 удаа лабораторийн шинжилгээгээр баталгаажуулна.", "h": "Монголын нөхцөлд анализаторыг халаалттай шүүгээнд байрлуулж, онлайн утгыг жилд 1–2 удаа лабораторийн шинжилгээгээр баталгаажуулна."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.3. Онлайн DGA анализаторын бүтцийн схем", "h": "Зураг 10.3. Онлайн DGA анализаторын бүтцийн схем"}, {"t": "h", "l": 2, "s": "2.1.3. IEC 60599-ийн харьцааны\nарга", "h": "2.1.3. IEC 60599-ийн харьцааны\nарга"}, {"t": "p", "s": "IEC 60599 нь гурван үндсэн харьцааг ашиглана: C 2H 2/C 2H 4, CH 4/H 2, C 2H 4/C 2H 6. Харьцаанд суурилсан арга нь тосны хэмжээ, хий алдагдлаас үл хамаарах давуу талтай. Харьцааг зөвхөн хийн агууламж ердийн утгаас давсан, эсвэл өсөх хурд өндөр үед хэрэглэнэ; хэвийн трансформаторын маш бага агууламжаас харьцаа тооцох нь худал дүгнэлтэд хүргэнэ. Гэмтлийн ангиллыг Хүснэгт 10.4-т үзүүлэв.", "h": "IEC 60599 нь гурван үндсэн харьцааг ашиглана: C<sub>2</sub>H<sub>2</sub>/C<sub>2</sub>H<sub>4</sub>, CH<sub>4</sub>/H<sub>2</sub>, C<sub>2</sub>H<sub>4</sub>/C<sub>2</sub>H<sub>6</sub>. Харьцаанд суурилсан арга нь тосны хэмжээ, хий алдагдлаас үл хамаарах давуу талтай. Харьцааг зөвхөн хийн агууламж ердийн утгаас давсан, эсвэл өсөх хурд өндөр үед хэрэглэнэ; хэвийн трансформаторын маш бага агууламжаас харьцаа тооцох нь худал дүгнэлтэд хүргэнэ. Гэмтлийн ангиллыг Хүснэгт 10.4-т үзүүлэв."}, {"t": "cap", "s": "Хүснэгт 10.4. IEC 60599-ийн харьцааны аргаар гэмтлийг тодорхойлох", "h": "Хүснэгт 10.4. IEC 60599-ийн харьцааны аргаар гэмтлийг тодорхойлох"}, {"t": "tbl", "s": "", "head": ["Гэмтэл", "Тайлбар", "C₂H₂/C₂H₄", "CH₄/H₂", "C₂H₄/C₂H₆"], "rows": [["PD", "Хэсэгчилсэн цэнэг (титэм)", "ач холбогдолгүй", "&lt; 0.1", "&lt; 0.2"], ["D1", "Бага энергийн цэнэг", "&gt; 1", "0.1–0.5", "&gt; 1"], ["D2", "Их энергийн цэнэг (нум)", "0.6–2.5", "0.1–1", "&gt; 2"], ["T1", "Дулааны гэмтэл, &lt; 300 °C", "ач холбогдолгүй", "&gt; 1", "&lt; 1"], ["T2", "Дулааны гэмтэл, 300–700 °C", "&lt; 0.1", "&gt; 1", "1–4"], ["T3", "Дулааны гэмтэл, &gt; 700 °C", "&lt; 0.2", "&gt; 1", "&gt; 4"]]}, {"t": "p", "s": "Рожерсийн арга (IEEE C57.104-2008-д орсон) нь мөн гурван харьцаа R 2=C 2H 2/C 2H 4, R 1=CH 4/H 2, R 5=C 2H 4/C 2H 6-ийг ашиглаж зургаан тохиолдлыг ялгана: 0 — хэвийн (R 2<0.1, 0.1≤R 1≤1, R 5<1); 1 — бага энергийн PD (R 2<0.1, R 1<0.1, R 5<1); 2 — их энергийн нум (0.1≤R 2≤3, 0.1≤R 1≤1, R 5>3); 3 — бага температурын халалт (R 2<0.1, 0.1≤R 1≤1, 1≤R 5≤3); 4 — 700 °C-ээс доош халалт (R 2<0.1, R 1>1, 1≤R 5≤3); 5 — 700 °C-ээс дээш халалт (R 2<0.1, R 1>1, R 5>3). Хүснэгтийн аль ч мөрөнд тохирохгүй хослол гарах нь харьцааны аргын нийтлэг сул тал бөгөөд энэ үед Дювалын гурвалжинг хэрэглэнэ.", "h": "<b>Рожерсийн арга</b> (IEEE C57.104-2008-д орсон) нь мөн гурван харьцаа R<sub>2</sub>=C<sub>2</sub>H<sub>2</sub>/C<sub>2</sub>H<sub>4</sub>, R<sub>1</sub>=CH<sub>4</sub>/H<sub>2</sub>, R<sub>5</sub>=C<sub>2</sub>H<sub>4</sub>/C<sub>2</sub>H<sub>6</sub>-ийг ашиглаж зургаан тохиолдлыг ялгана: 0 — хэвийн (R<sub>2</sub>&lt;0.1, 0.1≤R<sub>1</sub>≤1, R<sub>5</sub>&lt;1); 1 — бага энергийн PD (R<sub>2</sub>&lt;0.1, R<sub>1</sub>&lt;0.1, R<sub>5</sub>&lt;1); 2 — их энергийн нум (0.1≤R<sub>2</sub>≤3, 0.1≤R<sub>1</sub>≤1, R<sub>5</sub>&gt;3); 3 — бага температурын халалт (R<sub>2</sub>&lt;0.1, 0.1≤R<sub>1</sub>≤1, 1≤R<sub>5</sub>≤3); 4 — 700 °C-ээс доош халалт (R<sub>2</sub>&lt;0.1, R<sub>1</sub>&gt;1, 1≤R<sub>5</sub>≤3); 5 — 700 °C-ээс дээш халалт (R<sub>2</sub>&lt;0.1, R<sub>1</sub>&gt;1, R<sub>5</sub>&gt;3). Хүснэгтийн аль ч мөрөнд тохирохгүй хослол гарах нь харьцааны аргын нийтлэг сул тал бөгөөд энэ үед Дювалын гурвалжинг хэрэглэнэ."}, {"t": "p", "s": "Жишээ 10.2. 110/10 кВ, 25 МВА трансформаторын онлайн DGA: H₂ = 95, CH₄ = 120, C₂H₆ = 45, C₂H₄ = 250, C₂H₂ = 3, CO = 450, CO₂ = 3200 ppm. Гурван сарын өмнө C₂H₄ = 140 ppm байв. Гэмтлийг IEC 60599 ба Рожерсийн аргаар тодорхойлъё.", "h": "<b>Жишээ 10.2.</b> 110/10 кВ, 25 МВА трансформаторын онлайн DGA: H₂ = 95, CH₄ = 120, C₂H₆ = 45, C₂H₄ = 250, C₂H₂ = 3, CO = 450, CO₂ = 3200 ppm. Гурван сарын өмнө C₂H₄ = 140 ppm байв. Гэмтлийг IEC 60599 ба Рожерсийн аргаар тодорхойлъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. C₂H₄ нь ердийн мужийн дээд хэсэгт байгаа бөгөөд гурван сард 110 ppm (≈ 1.2 ppm/өдөр) өссөн тул харьцааны шинжилгээ хийх үндэслэлтэй. Харьцаа: C 2H 2/C 2H 4=3/250=0.012; CH 4/H 2=120/95=1.26; C 2H 4/C 2H 6=250/45=5.56.", "h": "<i>Бодолт.</i> C₂H₄ нь ердийн мужийн дээд хэсэгт байгаа бөгөөд гурван сард 110 ppm (≈ 1.2 ppm/өдөр) өссөн тул харьцааны шинжилгээ хийх үндэслэлтэй. Харьцаа: C<sub>2</sub>H<sub>2</sub>/C<sub>2</sub>H<sub>4</sub>=3/250=0.012; CH<sub>4</sub>/H<sub>2</sub>=120/95=1.26; C<sub>2</sub>H<sub>4</sub>/C<sub>2</sub>H<sub>6</sub>=250/45=5.56.", "x": "ex"}, {"t": "p", "s": "IEC 60599: 0.012<0.2, 1.26>1, 5.56>4 → T3, 700 °C-ээс дээш дулааны гэмтэл. Рожерс: R 2<0.1, R 1>1, R 5>3 → тохиолдол 5, мөн 700 °C-ээс дээш халалт. CO 2/CO=3200/450=7.1>3 тул цаас гэмтэлд оролцоогүй байх магадлалтай; иймээс тосонд дүрэгдсэн металл хэсгийн халалт — соронзон хүрээний олон цэгийн газардуулга, хүрээний ламелийн богино холбоо, гаргалгааны холбоос, сонгогчийн контакт — сэжиглэгдэнэ. Дараагийн алхам: хүрээний газардуулгын гүйдэл хэмжих, ороомгийн тогтмол гүйдлийн эсэргүүцлийг шилжүүлэгчийн байрлал бүрд хэмжих, DGA-ийн давтамжийг өсгөх.", "h": "IEC 60599: 0.012&lt;0.2, 1.26&gt;1, 5.56&gt;4 → <b>T3, 700 °C-ээс дээш дулааны гэмтэл</b>. Рожерс: R<sub>2</sub>&lt;0.1, R<sub>1</sub>&gt;1, R<sub>5</sub>&gt;3 → тохиолдол 5, мөн 700 °C-ээс дээш халалт. CO<sub>2</sub>/CO=3200/450=7.1&gt;3 тул цаас гэмтэлд оролцоогүй байх магадлалтай; иймээс тосонд дүрэгдсэн металл хэсгийн халалт — соронзон хүрээний олон цэгийн газардуулга, хүрээний ламелийн богино холбоо, гаргалгааны холбоос, сонгогчийн контакт — сэжиглэгдэнэ. Дараагийн алхам: хүрээний газардуулгын гүйдэл хэмжих, ороомгийн тогтмол гүйдлийн эсэргүүцлийг шилжүүлэгчийн байрлал бүрд хэмжих, DGA-ийн давтамжийг өсгөх.", "x": "ex"}, {"t": "h", "l": 2, "s": "2.1.4. Дювалын гурвалжин", "h": "2.1.4. Дювалын гурвалжин"}, {"t": "p", "s": "М.Дювалын (Duval) 1974 онд боловсруулсан гурвалжин нь CH₄, C₂H₄, C₂H₂ гурван хийн харьцангуй хувийг ашиглана:", "h": "М.Дювалын (Duval) 1974 онд боловсруулсан гурвалжин нь CH₄, C₂H₄, C₂H₂ гурван хийн харьцангуй хувийг ашиглана:"}, {"t": "eq", "s": "%CH 4=(100 x)/(x+y+z), %C 2H 4=(100 y)/(x+y+z), %C 2H 2=(100 z)/(x+y+z) (10.3)", "h": "%CH<sub>4</sub>=(100 x)/(x+y+z), %C<sub>2</sub>H<sub>4</sub>=(100 y)/(x+y+z), %C<sub>2</sub>H<sub>2</sub>=(100 z)/(x+y+z)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>%</mi><mi>C</mi><msub><mi>H</mi><mn>4</mn></msub><mo>=</mo><mfrac><mrow><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>x</mi></mrow><mrow><mi>x</mi><mo>+</mo><mi>y</mi><mo>+</mo><mi>z</mi></mrow></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>%</mi><msub><mi>C</mi><mn>2</mn></msub><msub><mi>H</mi><mn>4</mn></msub><mo>=</mo><mfrac><mrow><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>y</mi></mrow><mrow><mi>x</mi><mo>+</mo><mi>y</mi><mo>+</mo><mi>z</mi></mrow></mfrac><mo>,</mo><mspace width=\"2.0em\"></mspace><mi>%</mi><msub><mi>C</mi><mn>2</mn></msub><msub><mi>H</mi><mn>2</mn></msub><mo>=</mo><mfrac><mrow><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>z</mi></mrow><mrow><mi>x</mi><mo>+</mo><mi>y</mi><mo>+</mo><mi>z</mi></mrow></mfrac></mrow></semantics></math>", "n": "10.3"}, {"t": "p", "s": "энд x, y, z — CH₄, C₂H₄, C₂H₂-ийн агууламж, ppm. Гурван хувийн нийлбэр 100 тул цэг гурвалжны дотор заавал нэг бүсэд унана — энэ нь харьцааны аргын «тодорхойгүй» тохиолдлыг арилгадаг гол давуу тал юм. Дювалын гурвалжин 1 (Зураг 10.4) долоон бүстэй: PD, T1, T2, T3, D1, D2 ба DT (цахилгаан ба дулааны холимог гэмтэл). Бүсийн хил: PD — CH₄ ≥ 98 %; T1 — C₂H₂ < 4 %, C₂H₄ < 20 %; T2 — C₂H₂ < 4 %, C₂H₄ = 20–50 %; T3 — C₂H₂ < 15 %, C₂H₄ ≥ 50 %; D1 — C₂H₄ < 23 %, C₂H₂ > 13 %; D2 — C₂H₂ > 13 % ба C₂H₄ = 23–40 % эсвэл C₂H₂ > 29 % ба C₂H₄ > 40 %; бусад нь DT. Мөн эстер тос, OLTC-д зориулсан бусад гурвалжин, таван хийн «Дювалын таван өнцөгт» бий.", "h": "энд x, y, z — CH₄, C₂H₄, C₂H₂-ийн агууламж, ppm. Гурван хувийн нийлбэр 100 тул цэг гурвалжны дотор заавал нэг бүсэд унана — энэ нь харьцааны аргын «тодорхойгүй» тохиолдлыг арилгадаг гол давуу тал юм. Дювалын гурвалжин 1 (Зураг 10.4) долоон бүстэй: PD, T1, T2, T3, D1, D2 ба DT (цахилгаан ба дулааны холимог гэмтэл). Бүсийн хил: PD — CH₄ ≥ 98 %; T1 — C₂H₂ &lt; 4 %, C₂H₄ &lt; 20 %; T2 — C₂H₂ &lt; 4 %, C₂H₄ = 20–50 %; T3 — C₂H₂ &lt; 15 %, C₂H₄ ≥ 50 %; D1 — C₂H₄ &lt; 23 %, C₂H₂ &gt; 13 %; D2 — C₂H₂ &gt; 13 % ба C₂H₄ = 23–40 % эсвэл C₂H₂ &gt; 29 % ба C₂H₄ &gt; 40 %; бусад нь DT. Мөн эстер тос, OLTC-д зориулсан бусад гурвалжин, таван хийн «Дювалын таван өнцөгт» бий."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.4. Дювалын гурвалжин 1 ба Жишээ 10.2, 10.3-ын цэгүүд", "h": "Зураг 10.4. Дювалын гурвалжин 1 ба Жишээ 10.2, 10.3-ын цэгүүд"}, {"t": "p", "s": "Жишээ 10.3. 220 кВ-ын трансформаторын Бухгольцын реле дохио өгсний дараа авсан тосны шинжилгээ: H₂ = 300, CH₄ = 60, C₂H₆ = 20, C₂H₄ = 110, C₂H₂ = 80 ppm. Дювалын гурвалжин ба IEC 60599-ээр гэмтлийг тодорхойлж, Жишээ 10.2-ын дээжийг гурвалжинд байрлуулъя.", "h": "<b>Жишээ 10.3.</b> 220 кВ-ын трансформаторын Бухгольцын реле дохио өгсний дараа авсан тосны шинжилгээ: H₂ = 300, CH₄ = 60, C₂H₆ = 20, C₂H₄ = 110, C₂H₂ = 80 ppm. Дювалын гурвалжин ба IEC 60599-ээр гэмтлийг тодорхойлж, Жишээ 10.2-ын дээжийг гурвалжинд байрлуулъя.", "x": "ex"}, {"t": "p", "s": "Бодолт. (10.3)-аар нийлбэр 60+110+80=250 ppm; %CH₄ = 100⋅60/250=24.0 %, %C₂H₄ = 44.0 %, %C₂H₂ = 32.0 %. C₂H₂ = 32 % > 29 % ба C₂H₄ = 44 % > 40 % тул цэг D2 — их энергийн цахилгаан цэнэг (нум) бүсэд унана.", "h": "<i>Бодолт.</i> (10.3)-аар нийлбэр 60+110+80=250 ppm; %CH₄ = 100⋅60/250=24.0 %, %C₂H₄ = 44.0 %, %C₂H₂ = 32.0 %. C₂H₂ = 32 % &gt; 29 % ба C₂H₄ = 44 % &gt; 40 % тул цэг <b>D2 — их энергийн цахилгаан цэнэг (нум)</b> бүсэд унана.", "x": "ex"}, {"t": "p", "s": "IEC 60599-ээр шалгавал: C 2H 2/C 2H 4=80/110=0.73 (0.6–2.5), CH 4/H 2=60/300=0.20 (0.1–1), C 2H 4/C 2H 6=110/20=5.5 (> 2) → мөн D2. Хоёр арга давхцаж, Бухгольцын релений ажиллагаатай нийцэж байгаа тул трансформаторыг сүлжээнд дахин залгахгүй, дотоод үзлэг, ороомгийн туршилт (эргэлт хоорондын богино холбоо, FRA) хийнэ.", "h": "IEC 60599-ээр шалгавал: C<sub>2</sub>H<sub>2</sub>/C<sub>2</sub>H<sub>4</sub>=80/110=0.73 (0.6–2.5), CH<sub>4</sub>/H<sub>2</sub>=60/300=0.20 (0.1–1), C<sub>2</sub>H<sub>4</sub>/C<sub>2</sub>H<sub>6</sub>=110/20=5.5 (&gt; 2) → мөн D2. Хоёр арга давхцаж, Бухгольцын релений ажиллагаатай нийцэж байгаа тул трансформаторыг сүлжээнд дахин залгахгүй, дотоод үзлэг, ороомгийн туршилт (эргэлт хоорондын богино холбоо, FRA) хийнэ.", "x": "ex"}, {"t": "p", "s": "Жишээ 10.2-ын дээж: нийлбэр 120+250+3=373 ppm; %CH₄ = 32.2 %, %C₂H₄ = 67.0 %, %C₂H₂ = 0.8 % → C₂H₄ ≥ 50 %, C₂H₂ < 15 % тул T3, харьцааны аргатай давхцаж байна (Зураг 10.4-ийн Ж1 цэг).", "h": "Жишээ 10.2-ын дээж: нийлбэр 120+250+3=373 ppm; %CH₄ = 32.2 %, %C₂H₄ = 67.0 %, %C₂H₂ = 0.8 % → C₂H₄ ≥ 50 %, C₂H₂ &lt; 15 % тул <b>T3</b>, харьцааны аргатай давхцаж байна (Зураг 10.4-ийн Ж1 цэг).", "x": "ex"}, {"t": "h", "l": 2, "s": "2.2. Тос ба цаасны чийг", "h": "2.2. Тос ба цаасны чийг"}, {"t": "p", "s": "Чийг нь цаасан тусгаарлагын «гурван дайсан» (чийг, хүчилтөрөгч, температур)-ы нэг: цаасны чийг 1 %-иас 2 % хүрэхэд хөгшрөлтийн хурд ойролцоогоор хоёр дахин өсөж, цахилгаан бат бэх буурч, хэт ачааллын үед ороомгоос усны уурын бөмбөлөг (bubble) ялгарах эрсдэл үүснэ. Трансформатор доторх усны 95 %-иас илүү нь цаасанд байх ба температур өөрчлөгдөхөд тос, цаасны хооронд шилжинэ.", "h": "Чийг нь цаасан тусгаарлагын «гурван дайсан» (чийг, хүчилтөрөгч, температур)-ы нэг: цаасны чийг 1 %-иас 2 % хүрэхэд хөгшрөлтийн хурд ойролцоогоор хоёр дахин өсөж, цахилгаан бат бэх буурч, хэт ачааллын үед ороомгоос усны уурын бөмбөлөг (bubble) ялгарах эрсдэл үүснэ. Трансформатор доторх усны 95 %-иас илүү нь цаасанд байх ба температур өөрчлөгдөхөд тос, цаасны хооронд шилжинэ."}, {"t": "p", "s": "Онлайн мэдрэгч (багтаамжит полимер мэдрэгч) нь тосны харьцангуй ханалт RS-ийг шууд хэмжинэ. Эрдэс тосны усны уусах чадвар (ханалтын агууламж) температураас экспоненциал хамаардаг:", "h": "Онлайн мэдрэгч (багтаамжит полимер мэдрэгч) нь тосны <b>харьцангуй ханалт</b> RS-ийг шууд хэмжинэ. Эрдэс тосны усны уусах чадвар (ханалтын агууламж) температураас экспоненциал хамаардаг:"}, {"t": "eq", "s": "lgW s=A−B/T (10.4)", "h": "lgW<sub>s</sub>=A−B/T", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>lg</mo><msub><mi>W</mi><mi>s</mi></msub><mo>=</mo><mi>A</mi><mo>−</mo><mfrac><mi>B</mi><mi>T</mi></mfrac></mrow></semantics></math>", "n": "10.4"}, {"t": "p", "s": "энд W s — ханалтын агууламж, ppm; T — температур, К; шинэ эрдэс тосны хувьд ойролцоогоор A=7.42, B=1670 К (тос хөгшрөхөд W s өснө). (10.4)-өөр W s нь 20 °C-д 53 ppm, 40 °C-д 122 ppm, 60 °C-д 255 ppm болно. Тосны усны агууламж", "h": "энд W<sub>s</sub> — ханалтын агууламж, ppm; T — температур, К; шинэ эрдэс тосны хувьд ойролцоогоор A=7.42, B=1670 К (тос хөгшрөхөд W<sub>s</sub> өснө). (10.4)-өөр W<sub>s</sub> нь 20 °C-д 53 ppm, 40 °C-д 122 ppm, 60 °C-д 255 ppm болно. Тосны усны агууламж"}, {"t": "eq", "s": "W=RS⋅W s(T) (10.5)", "h": "W=RS⋅W<sub>s</sub>(T)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi><mo>=</mo><mi>R</mi><mi>S</mi><mo>⋅</mo><msub><mi>W</mi><mi>s</mi></msub><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mi>T</mi><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "10.5"}, {"t": "p", "s": "Жишээ нь 60 °C-д RS=12 % бол W=0.12⋅255=31 ppm. Энэ тосыг 20 °C-д хөргөхөд RS=31/53=58 % болж, хүйтэн нөхцөлд чөлөөт ус ялгарах эрсдэлд ойртоно. Монголын өвлийн хүйтэнд ачаалал багатай трансформаторын тос −20…−30 °C хүртэл хөрөх тул энэ асуудал онцгой чухал. Цаасны чийгийг тос-цаасны тэнцвэрийн муруйгаар тогтвортой ачааллын үед үнэлнэ. IEC 60422 нь тосны чийгийг 20 °C-д шилжүүлсэн утгаар, хүчдэлийн ангиллаар («сайн», «хангалттай», «муу») үнэлэх зааврыг өгдөг.", "h": "Жишээ нь 60 °C-д RS=12 % бол W=0.12⋅255=31 ppm. Энэ тосыг 20 °C-д хөргөхөд RS=31/53=58 % болж, хүйтэн нөхцөлд чөлөөт ус ялгарах эрсдэлд ойртоно. Монголын өвлийн хүйтэнд ачаалал багатай трансформаторын тос −20…−30 °C хүртэл хөрөх тул энэ асуудал онцгой чухал. Цаасны чийгийг тос-цаасны тэнцвэрийн муруйгаар тогтвортой ачааллын үед үнэлнэ. IEC 60422 нь тосны чийгийг 20 °C-д шилжүүлсэн утгаар, хүчдэлийн ангиллаар («сайн», «хангалттай», «муу») үнэлэх зааврыг өгдөг."}, {"t": "p", "s": "Цаасны хөгшрөлтийн шууд үзүүлэлт нь полимержилтийн зэрэг (DP) юм: шинэ цаасны DP ≈ 1000–1200, DP ≈ 200 хүрэхэд цаас механик бат бэхээ алдаж, трансформаторын «амьдралын төгсгөл» гэж үзнэ. DP-г ажиллагаанд байгаа трансформатороос шууд хэмжих боломжгүй тул тосонд уусах фураны нэгдэл, ялангуяа 2-фурфуралын (2-FAL) агууламжаар Чендуны (Chendong) эмпирик хамаарлаар үнэлдэг: DP≈(1.51−lgC 2FAL)/0.0035, энд C 2FAL — мг/кг. Жишээ нь C 2FAL=1.2 мг/кг бол DP≈409, өөрөөр хэлбэл цаас ашиглалтын хугацааныхаа дунд хэсгийг өнгөрсөн байна.", "h": "Цаасны хөгшрөлтийн шууд үзүүлэлт нь полимержилтийн зэрэг (DP) юм: шинэ цаасны DP ≈ 1000–1200, DP ≈ 200 хүрэхэд цаас механик бат бэхээ алдаж, трансформаторын «амьдралын төгсгөл» гэж үзнэ. DP-г ажиллагаанд байгаа трансформатороос шууд хэмжих боломжгүй тул тосонд уусах фураны нэгдэл, ялангуяа 2-фурфуралын (2-FAL) агууламжаар Чендуны (Chendong) эмпирик хамаарлаар үнэлдэг: DP≈(1.51−lgC<sub>2FAL</sub>)/0.0035, энд C<sub>2FAL</sub> — мг/кг. Жишээ нь C<sub>2FAL</sub>=1.2 мг/кг бол DP≈409, өөрөөр хэлбэл цаас ашиглалтын хугацааныхаа дунд хэсгийг өнгөрсөн байна."}, {"t": "h", "l": 2, "s": "2.3. Оруулгын хяналт", "h": "2.3. Оруулгын хяналт"}, {"t": "p", "s": "Өндөр хүчдэлийн конденсатор төрлийн оруулга (OIP — тосонд нэвчүүлсэн цаас, RIP — давирхайд нэвчүүлсэн цаас, RIS — давирхайд нэвчүүлсэн синтетик) нь гол дамжуулагчийн эргэн тойронд цуваа холбогдсон олон конденсаторын давхаргаас тогтоно. Гол дамжуулагч ба хэмжилтийн гаргалгааны (test tap) хоорондох багтаамжийг C1, гаргалгаа ба газрын хоорондох багтаамжийг C2 гэнэ. Онлайн хяналтад гаргалгаанд мэдрэгч (adapter) холбож, тусгаарлагаар гүйх багтаамжийн гүйдлийг хэмжинэ:", "h": "Өндөр хүчдэлийн конденсатор төрлийн оруулга (OIP — тосонд нэвчүүлсэн цаас, RIP — давирхайд нэвчүүлсэн цаас, RIS — давирхайд нэвчүүлсэн синтетик) нь гол дамжуулагчийн эргэн тойронд цуваа холбогдсон олон конденсаторын давхаргаас тогтоно. Гол дамжуулагч ба хэмжилтийн гаргалгааны (test tap) хоорондох багтаамжийг <b>C1</b>, гаргалгаа ба газрын хоорондох багтаамжийг <b>C2</b> гэнэ. Онлайн хяналтад гаргалгаанд мэдрэгч (adapter) холбож, тусгаарлагаар гүйх багтаамжийн гүйдлийг хэмжинэ:"}, {"t": "eq", "s": "I C=U ф ω C 1, tgδ=I R/I C (10.6)", "h": "I<sub>C</sub>=U<sub>ф</sub> ω C<sub>1</sub>, tgδ=I<sub>R</sub>/I<sub>C</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I</mi><mi>C</mi></msub><mo>=</mo><msub><mi>U</mi><mi>ф</mi></msub><mspace width=\"0.167em\"></mspace><mi>ω</mi><mspace width=\"0.167em\"></mspace><msub><mi>C</mi><mn>1</mn></msub><mo>,</mo><mspace width=\"2.0em\"></mspace><mo>tg</mo><mi>δ</mi><mo>=</mo><mfrac><msub><mi>I</mi><mi>R</mi></msub><msub><mi>I</mi><mi>C</mi></msub></mfrac></mrow></semantics></math>", "n": "10.6"}, {"t": "p", "s": "энд U ф — фазын хүчдэл, В; ω=2πf; I R — гүйдлийн идэвхтэй (алдагдлын) байгуулагч. Хэрэв n давхаргын нэг нь цоорч богино холбогдвол үлдсэн n−1 давхарга цуваа холбогдож, багтаамж", "h": "энд U<sub>ф</sub> — фазын хүчдэл, В; ω=2πf; I<sub>R</sub> — гүйдлийн идэвхтэй (алдагдлын) байгуулагч. Хэрэв n давхаргын нэг нь цоорч богино холбогдвол үлдсэн n−1 давхарга цуваа холбогдож, багтаамж"}, {"t": "eq", "s": "(ΔC 1)/C 1=n/(n−1)−1=1/(n−1) (10.7)", "h": "(ΔC<sub>1</sub>)/C<sub>1</sub>=n/(n−1)−1=1/(n−1)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>Δ</mi><msub><mi>C</mi><mn>1</mn></msub></mrow><msub><mi>C</mi><mn>1</mn></msub></mfrac><mo>=</mo><mfrac><mi>n</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></mfrac><mo>−</mo><mn>1</mn><mo>=</mo><mfrac><mn>1</mn><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></mfrac></mrow></semantics></math>", "n": "10.7"}, {"t": "p", "s": "-ээр өснө. Хүчдэлийн хэлбэлзлийн нөлөөг гурван фазын гүйдлийн нийлбэр эсвэл жишиг оруулгатай харьцуулах аргаар арилгана. Ерөнхий зөвлөмжөөр C1 нь анхны утгаас 5 %-иас их өөрчлөгдвөл судлах, 10 % давбал ашиглалтаас гаргах; OIP оруулгын tanδ (20 °C-д) 0.5 % орчим байх ба анхны утгаас хоёр дахин өсөх нь чийг орсон, эсвэл тусгаарлага муудсаны шинж юм.", "h": "-ээр өснө. Хүчдэлийн хэлбэлзлийн нөлөөг гурван фазын гүйдлийн нийлбэр эсвэл жишиг оруулгатай харьцуулах аргаар арилгана. Ерөнхий зөвлөмжөөр C1 нь анхны утгаас 5 %-иас их өөрчлөгдвөл судлах, 10 % давбал ашиглалтаас гаргах; OIP оруулгын tanδ (20 °C-д) 0.5 % орчим байх ба анхны утгаас хоёр дахин өсөх нь чийг орсон, эсвэл тусгаарлага муудсаны шинж юм."}, {"t": "p", "s": "Жишээ 10.4. U m=126 кВ-ын OIP оруулгын C 1=400 пФ, конденсаторын давхаргын тоо n=30, tanδ = 0.4 %. (а) Хэвийн багтаамжийн гүйдэл, алдагдлын чадал; (б) нэг давхарга цоорсон үеийн C1-ийн өөрчлөлт ба нийлбэр гүйдлийн өөрчлөлт; (в) tanδ 0.8 % болсон үеийн алдагдлыг тооцъё.", "h": "<b>Жишээ 10.4.</b> U<sub>m</sub>=126 кВ-ын OIP оруулгын C<sub>1</sub>=400 пФ, конденсаторын давхаргын тоо n=30, tanδ = 0.4 %. (а) Хэвийн багтаамжийн гүйдэл, алдагдлын чадал; (б) нэг давхарга цоорсон үеийн C1-ийн өөрчлөлт ба нийлбэр гүйдлийн өөрчлөлт; (в) tanδ 0.8 % болсон үеийн алдагдлыг тооцъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (а) U ф=126/√(3)=72.7 кВ. (10.6)-аар I C=72 746⋅314.16⋅400⋅10^−12=9.14 мА. I R=0.004⋅9.14=36.6 мкА, алдагдал P=U фI Ctgδ=72 746⋅9.14⋅10^−3⋅0.004=2.66 Вт.", "h": "<i>Бодолт.</i> (а) U<sub>ф</sub>=126/√(3)=72.7 кВ. (10.6)-аар I<sub>C</sub>=72 746⋅314.16⋅400⋅10<sup>−12</sup>=9.14 мА. I<sub>R</sub>=0.004⋅9.14=36.6 мкА, алдагдал P=U<sub>ф</sub>I<sub>C</sub>tgδ=72 746⋅9.14⋅10<sup>−3</sup>⋅0.004=2.66 Вт.", "x": "ex"}, {"t": "p", "s": "(б) (10.7)-оор ΔC 1/C 1=1/29=3.45 %, C 1′=413.8 пФ. Гурван фазын тэгш хэмтэй үед нийлбэр гүйдэл тэг байх ба нэг фазын гүйдэл 3.45 %-иар өсөхөд нийлбэр гүйдэл 0.0345⋅9.14=0.315 мА болно. Энэ нь 5 %-ийн «судлах» босгоос бага боловч хурдан өөрчлөлт (нэг өдөрт) учраас анхааруулах дохио өгөх ёстой; дараагийн давхарга цоорох тусам цахилгаан оронд ачаалал нэмэгдэж, гэмтэл хурдасна.", "h": "(б) (10.7)-оор ΔC<sub>1</sub>/C<sub>1</sub>=1/29=3.45 %, C<sub>1</sub>′=413.8 пФ. Гурван фазын тэгш хэмтэй үед нийлбэр гүйдэл тэг байх ба нэг фазын гүйдэл 3.45 %-иар өсөхөд нийлбэр гүйдэл 0.0345⋅9.14=0.315 мА болно. Энэ нь 5 %-ийн «судлах» босгоос бага боловч хурдан өөрчлөлт (нэг өдөрт) учраас анхааруулах дохио өгөх ёстой; дараагийн давхарга цоорох тусам цахилгаан оронд ачаалал нэмэгдэж, гэмтэл хурдасна.", "x": "ex"}, {"t": "p", "s": "(в) tanδ = 0.8 %: I R=73.1 мкА, P=5.32 Вт — алдагдал хоёр дахин өсөж, тусгаарлагын дотоод халалт нэмэгдэн «дулааны нуралт»-ын эрсдэл бий болно.", "h": "(в) tanδ = 0.8 %: I<sub>R</sub>=73.1 мкА, P=5.32 Вт — алдагдал хоёр дахин өсөж, тусгаарлагын дотоод халалт нэмэгдэн «дулааны нуралт»-ын эрсдэл бий болно.", "x": "ex"}, {"t": "h", "l": 2, "s": "2.4. Дулааны хяналт ба\nхөгшрөлт (IEC 60076-7)", "h": "2.4. Дулааны хяналт ба\nхөгшрөлт (IEC 60076-7)"}, {"t": "p", "s": "Трансформаторын ашиглалтын хугацааг цаасан тусгаарлагын хамгийн халуун цэгийн (hot-spot) температур тодорхойлно. Халуун цэгийн температурыг шилэн кабелийн мэдрэгчээр шууд хэмжих (шинэ трансформаторт 4–8 мэдрэгч), эсвэл дээд тосны температур, ачааллын гүйдлээр IEC 60076-7-ийн дулааны загвараар тооцоолно. Тогтвортой горимд:", "h": "Трансформаторын ашиглалтын хугацааг цаасан тусгаарлагын хамгийн халуун цэгийн (hot-spot) температур тодорхойлно. Халуун цэгийн температурыг шилэн кабелийн мэдрэгчээр шууд хэмжих (шинэ трансформаторт 4–8 мэдрэгч), эсвэл дээд тосны температур, ачааллын гүйдлээр IEC 60076-7-ийн дулааны загвараар тооцоолно. Тогтвортой горимд:"}, {"t": "eq", "s": "θ h=θ a+Δθ or[(1+R K^2)/(1+R)]^x+H g r K^y (10.8)", "h": "θ<sub>h</sub>=θ<sub>a</sub>+Δθ<sub>or</sub>[(1+R K<sup>2</sup>)/(1+R)]<sup>x</sup>+H g<sub>r</sub> K<sup>y</sup>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>h</mi></msub><mo>=</mo><msub><mi>θ</mi><mi>a</mi></msub><mo>+</mo><mi>Δ</mi><msub><mi>θ</mi><mrow><mi>o</mi><mi>r</mi></mrow></msub><msup><mrow><mo form=\"prefix\" stretchy=\"true\">[</mo><mfrac><mrow><mn>1</mn><mo>+</mo><mi>R</mi><mspace width=\"0.167em\"></mspace><msup><mi>K</mi><mn>2</mn></msup></mrow><mrow><mn>1</mn><mo>+</mo><mi>R</mi></mrow></mfrac><mo form=\"postfix\" stretchy=\"true\">]</mo></mrow><mi>x</mi></msup><mo>+</mo><mi>H</mi><mspace width=\"0.167em\"></mspace><msub><mi>g</mi><mi>r</mi></msub><mspace width=\"0.167em\"></mspace><msup><mi>K</mi><mi>y</mi></msup></mrow></semantics></math>", "n": "10.8"}, {"t": "p", "s": "энд θ a — орчны температур, °C; Δθ or — нэрлэсэн ачааллын үеийн дээд тосны хэт халалт, К; R — нэрлэсэн ачааллын үеийн богино залгааны ба сул явалтын алдагдлын харьцаа; K — ачааллын коэффициент (нэрлэсэн чадлын хувиар); H — халуун цэгийн коэффициент (1.1–1.3); g r — ороомгийн дундаж ба тосны дундаж температурын зөрүү, К; x, y — тос ба ороомгийн илтгэгч (ONAN, ONAF хөргөлтөд x=0.8, y=1.3).", "h": "энд θ<sub>a</sub> — орчны температур, °C; Δθ<sub>or</sub> — нэрлэсэн ачааллын үеийн дээд тосны хэт халалт, К; R — нэрлэсэн ачааллын үеийн богино залгааны ба сул явалтын алдагдлын харьцаа; K — ачааллын коэффициент (нэрлэсэн чадлын хувиар); H — халуун цэгийн коэффициент (1.1–1.3); g<sub>r</sub> — ороомгийн дундаж ба тосны дундаж температурын зөрүү, К; x, y — тос ба ороомгийн илтгэгч (ONAN, ONAF хөргөлтөд x=0.8, y=1.3)."}, {"t": "p", "s": "Тусгаарлагын харьцангуй хөгшрөлтийн хурд нь энгийн (дулаанд тэсвэржүүлээгүй) цаасны хувьд", "h": "Тусгаарлагын <b>харьцангуй хөгшрөлтийн хурд</b> нь энгийн (дулаанд тэсвэржүүлээгүй) цаасны хувьд"}, {"t": "eq", "s": "V=2^(θ h−98)/6 (10.9)", "h": "V=2<sup>(θ<sub>h</sub>−98)/6</sup>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mo>=</mo><msup><mn>2</mn><mrow><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>θ</mi><mi>h</mi></msub><mo>−</mo><mn>98</mn><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mi>/</mi><mn>6</mn></mrow></msup></mrow></semantics></math>", "n": "10.9"}, {"t": "p", "s": "өөрөөр хэлбэл 98 °C-д V=1, температур 6 К-ээр өсөх бүрд хурд хоёр дахин өснө. Дулаанд тэсвэржүүлсэн (thermally upgraded) цаасны хувьд", "h": "өөрөөр хэлбэл 98 °C-д V=1, температур 6 К-ээр өсөх бүрд хурд хоёр дахин өснө. Дулаанд тэсвэржүүлсэн (thermally upgraded) цаасны хувьд"}, {"t": "eq", "s": "V=exp((15 000)/(110+273)−(15 000)/(θ h+273)) (10.10)", "h": "V=exp((15 000)/(110+273)−(15 000)/(θ<sub>h</sub>+273))", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mo>=</mo><mo>exp</mo><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mfrac><mrow><mn>15</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><mrow><mn>110</mn><mo>+</mo><mn>273</mn></mrow></mfrac><mo>−</mo><mfrac><mrow><mn>15</mn><mspace width=\"0.167em\"></mspace><mn>000</mn></mrow><mrow><msub><mi>θ</mi><mi>h</mi></msub><mo>+</mo><mn>273</mn></mrow></mfrac><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "10.10"}, {"t": "p", "s": "ба 110 °C-д V=1 байна. t 1-ээс t 2 хүртэлх хугацааны ашиглалтын хугацааны зарцуулалт", "h": "ба 110 °C-д V=1 байна. t<sub>1</sub>-ээс t<sub>2</sub> хүртэлх хугацааны <b>ашиглалтын хугацааны зарцуулалт</b>"}, {"t": "eq", "s": "L=∫ t1^t 2V dt≈∑ nV n t n (10.11)", "h": "L=∫<sub>t<sub>1</sub></sub><sup>t<sub>2</sub></sup>V dt≈∑<sub>n</sub>V<sub>n</sub> t<sub>n</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi><mo>=</mo><msubsup><mo>∫</mo><msub><mi>t</mi><mn>1</mn></msub><msub><mi>t</mi><mn>2</mn></msub></msubsup><mi>V</mi><mspace width=\"0.167em\"></mspace><mi>d</mi><mi>t</mi><mo>≈</mo><munder><mo>∑</mo><mi>n</mi></munder><msub><mi>V</mi><mi>n</mi></msub><mspace width=\"0.167em\"></mspace><msub><mi>t</mi><mi>n</mi></msub></mrow></semantics></math>", "n": "10.11"}, {"t": "p", "s": "IEC 60076-7 нь лавлах температурт хэвийн ашиглалтын хугацааг 180 000 ц (≈ 20.5 жил) гэж харьцуулах суурь болгон авдаг. Мөчлөгт ачааллын үед халуун цэг 120 °C, дээд тос 105 °C-ээс хэтрэхгүй байхыг зөвлөдөг. Хоёр төрлийн цаасны хурдыг Зураг 10.5,а-д харьцуулав.", "h": "IEC 60076-7 нь лавлах температурт хэвийн ашиглалтын хугацааг 180 000 ц (≈ 20.5 жил) гэж харьцуулах суурь болгон авдаг. Мөчлөгт ачааллын үед халуун цэг 120 °C, дээд тос 105 °C-ээс хэтрэхгүй байхыг зөвлөдөг. Хоёр төрлийн цаасны хурдыг Зураг 10.5,а-д харьцуулав."}, {"t": "p", "s": "Жишээ 10.5. 110/10 кВ, ONAN хөргөлттэй трансформатор (энгийн цаас): Δθ or=52 К, Hg r=26 К, R=6, x=0.8, y=1.3. Хоногийн ачаалал: 8 ц K=0.6, 10 ц K=0.9, 4 ц K=1.1, 2 ц K=0.8. Зуны θ a=+30 °C ба өвлийн θ a=−25 °C үеийн хоногийн хөгшрөлтийг тооцъё.", "h": "<b>Жишээ 10.5.</b> 110/10 кВ, ONAN хөргөлттэй трансформатор (энгийн цаас): Δθ<sub>or</sub>=52 К, Hg<sub>r</sub>=26 К, R=6, x=0.8, y=1.3. Хоногийн ачаалал: 8 ц K=0.6, 10 ц K=0.9, 4 ц K=1.1, 2 ц K=0.8. Зуны θ<sub>a</sub>=+30 °C ба өвлийн θ<sub>a</sub>=−25 °C үеийн хоногийн хөгшрөлтийг тооцъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (10.8)-аар θ a=+30 °C үед: K=0.6 — θ h=70.9 °C; K=0.9 — 97.8 °C; K=1.1 — 118.8 °C; K=0.8 — 88.2 °C. (10.9)-өөр V = 0.044; 0.975; 11.04; 0.321. (10.11)-ээр L=0.044⋅8+0.975⋅10+11.04⋅4+0.321⋅2=0.35+9.75+44.18+0.64=54.9 ц. Нэг хоногт 2.3 хоногийн хөгшрөлт зарцуулж байгаа бөгөөд үүний 80 %-ийг ердөө 4 цагийн оргил ачаалал үүсгэж байна.", "h": "<i>Бодолт.</i> (10.8)-аар θ<sub>a</sub>=+30 °C үед: K=0.6 — θ<sub>h</sub>=70.9 °C; K=0.9 — 97.8 °C; K=1.1 — 118.8 °C; K=0.8 — 88.2 °C. (10.9)-өөр V = 0.044; 0.975; 11.04; 0.321. (10.11)-ээр L=0.044⋅8+0.975⋅10+11.04⋅4+0.321⋅2=0.35+9.75+44.18+0.64=54.9 ц. Нэг хоногт 2.3 хоногийн хөгшрөлт зарцуулж байгаа бөгөөд үүний 80 %-ийг ердөө 4 цагийн оргил ачаалал үүсгэж байна.", "x": "ex"}, {"t": "p", "s": "θ a=−25 °C үед халуун цэг 55 К-ээр бага (15.9; 42.8; 63.8; 33.2 °C) тул L=0.096 ц — бараг хөгшрөхгүй. Иймээс Монголын нөхцөлд өвлийн оргил ачааллыг дулааны хувьд чөлөөтэй даах боломжтой: жишээ нь θ a=−30 °C-д K=1.5 ачаалалд θ h=107.2 °C, V=2.9 болох ба хэдэн цагийн аваарын ачаалал хүлээн зөвшөөрөгдөнө. Харин зуны халуунд хэт ачаалал хурдан хөгшрөлтөд хүргэнэ. Онлайн температурын хяналтад тулгуурласан динамик үнэлгээ (dynamic rating) энэ нөөцийг ашиглах боломж олгоно.", "h": "θ<sub>a</sub>=−25 °C үед халуун цэг 55 К-ээр бага (15.9; 42.8; 63.8; 33.2 °C) тул L=0.096 ц — бараг хөгшрөхгүй. Иймээс Монголын нөхцөлд өвлийн оргил ачааллыг дулааны хувьд чөлөөтэй даах боломжтой: жишээ нь θ<sub>a</sub>=−30 °C-д K=1.5 ачаалалд θ<sub>h</sub>=107.2 °C, V=2.9 болох ба хэдэн цагийн аваарын ачаалал хүлээн зөвшөөрөгдөнө. Харин зуны халуунд хэт ачаалал хурдан хөгшрөлтөд хүргэнэ. Онлайн температурын хяналтад тулгуурласан динамик үнэлгээ (dynamic rating) энэ нөөцийг ашиглах боломж олгоно.", "x": "ex"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.5. а) Тусгаарлагын хөгшрөлтийн харьцангуй хурд; б) Жишээ 10.5-ын халуун цэгийн температур", "h": "Зураг 10.5. а) Тусгаарлагын хөгшрөлтийн харьцангуй хурд; б) Жишээ 10.5-ын халуун цэгийн температур"}, {"t": "h", "l": 2, "s": "2.5. Ачаалал дор\nшилжүүлэгчийн (OLTC) хяналт", "h": "2.5. Ачаалал дор\nшилжүүлэгчийн (OLTC) хяналт"}, {"t": "p", "s": "OLTC нь трансформаторын цорын ганц хөдөлгөөнт хэсэг бөгөөд жилд хэдэн мянган удаа шилжинэ. Түүний онлайн хяналтын үндсэн параметрүүд:", "h": "OLTC нь трансформаторын цорын ганц хөдөлгөөнт хэсэг бөгөөд жилд хэдэн мянган удаа шилжинэ. Түүний онлайн хяналтын үндсэн параметрүүд:"}, {"t": "p", "s": "Хөтлүүрийн моментын эсвэл цахилгаан хөдөлгүүрийн чадлын муруй — шилжилт бүрийн чадлын «хээ»-г жишиг муруйтай харьцуулж, пүршний сулрал, араа, холхивчийн гэмтэл, контактын гацалтыг илрүүлнэ;", "h": "• <b>Хөтлүүрийн моментын эсвэл цахилгаан хөдөлгүүрийн чадлын муруй</b> — шилжилт бүрийн чадлын «хээ»-г жишиг муруйтай харьцуулж, пүршний сулрал, араа, холхивчийн гэмтэл, контактын гацалтыг илрүүлнэ;"}, {"t": "p", "s": "Шилжилтийн тоо ба тасалсан гүйдлийн нийлбэр — дивертер контактын элэгдлийг үнэлж, засварын хугацааг төлөвлөнө;", "h": "• <b>Шилжилтийн тоо ба тасалсан гүйдлийн нийлбэр</b> — дивертер контактын элэгдлийг үнэлж, засварын хугацааг төлөвлөнө;"}, {"t": "p", "s": "OLTC ба үндсэн савны тосны температурын зөрүү — сонгогч эсвэл дивертер контактын хэт халалт (кокслох) үед OLTC-ийн тос үндсэн савныхаас тогтвортой халуун болно;", "h": "• <b>OLTC ба үндсэн савны тосны температурын зөрүү</b> — сонгогч эсвэл дивертер контактын хэт халалт (кокслох) үед OLTC-ийн тос үндсэн савныхаас тогтвортой халуун болно;"}, {"t": "p", "s": "OLTC-ийн тосны DGA — нум унтраах хэвийн үйл ажиллагаанаас C₂H₂ их хэмжээгээр үүсдэг тул үндсэн савны аргачлалыг шууд хэрэглэхгүй; харин үндсэн саванд C₂H₂ аажмаар өсөх нь OLTC-оос нэвчилт байгааг илтгэж болно.", "h": "• <b>OLTC-ийн тосны DGA</b> — нум унтраах хэвийн үйл ажиллагаанаас C₂H₂ их хэмжээгээр үүсдэг тул үндсэн савны аргачлалыг шууд хэрэглэхгүй; харин үндсэн саванд C₂H₂ аажмаар өсөх нь OLTC-оос нэвчилт байгааг илтгэж болно."}, {"t": "p", "s": "Вакуум OLTC (Лекц 4)-д тос бохирдохгүй тул хяналт механизм, хөтлүүрт төвлөрнө.", "h": "Вакуум OLTC (Лекц 4)-д тос бохирдохгүй тул хяналт механизм, хөтлүүрт төвлөрнө."}, {"t": "h", "l": 1, "s": "3. Хэсэгчилсэн цэнэг", "h": "3. Хэсэгчилсэн цэнэг"}, {"t": "h", "l": 2, "s": "3.1. Физик ба илэрхий цэнэг", "h": "3.1. Физик ба илэрхий цэнэг"}, {"t": "p", "s": "Хэсэгчилсэн цэнэг (partial discharge, PD) гэдэг нь электродуудын хоорондох тусгаарлагын зөвхөн хэсгийг гүүрлэх локаль цахилгаан цохилт юм. Хийн хөндий, бөмбөлөг, хурц ирмэг, гадаргын бохирдол, хөвөгч потенциалтай металл зэрэг газарт орны хүч локаль хэмжээнд цохилтын утгаас давахад үүснэ. Нэг цэнэг нь пикокулон–нанокулоны (пКл–нКл) хэмжээтэй, наносекундын үргэлжлэлтэй гүйдлийн импульс, цахилгаан соронзон цацрал (100 МГц–3 ГГц), акустик долгион, гэрэл, хими задрал үүсгэнэ. Удаан хугацааны PD нь тусгаарлагыг эрозод оруулж, «модны мөчир» хэлбэрийн суваг (treeing) үүсгэн эцэстээ бүрэн цохилтод хүргэдэг.", "h": "<b>Хэсэгчилсэн цэнэг</b> (partial discharge, PD) гэдэг нь электродуудын хоорондох тусгаарлагын зөвхөн хэсгийг гүүрлэх локаль цахилгаан цохилт юм. Хийн хөндий, бөмбөлөг, хурц ирмэг, гадаргын бохирдол, хөвөгч потенциалтай металл зэрэг газарт орны хүч локаль хэмжээнд цохилтын утгаас давахад үүснэ. Нэг цэнэг нь пикокулон–нанокулоны (пКл–нКл) хэмжээтэй, наносекундын үргэлжлэлтэй гүйдлийн импульс, цахилгаан соронзон цацрал (100 МГц–3 ГГц), акустик долгион, гэрэл, хими задрал үүсгэнэ. Удаан хугацааны PD нь тусгаарлагыг эрозод оруулж, «модны мөчир» хэлбэрийн суваг (treeing) үүсгэн эцэстээ бүрэн цохилтод хүргэдэг."}, {"t": "p", "s": "Хөндийн цэнэгийг abc загвараар тайлбарладаг: C c — хөндийн багтаамж, C b — хөндийтэй цуваа орших эрүүл тусгаарлагын багтаамж, C a — үлдсэн тусгаарлагын багтаамж. Хөндий цохигдоход түүн дэх хүчдэл ΔU c-ээр огцом буурах ба гадаад хэлхээнээс хэмжигдэх илэрхий цэнэг (apparent charge) нь", "h": "Хөндийн цэнэгийг <b>abc загвар</b>аар тайлбарладаг: C<sub>c</sub> — хөндийн багтаамж, C<sub>b</sub> — хөндийтэй цуваа орших эрүүл тусгаарлагын багтаамж, C<sub>a</sub> — үлдсэн тусгаарлагын багтаамж. Хөндий цохигдоход түүн дэх хүчдэл ΔU<sub>c</sub>-ээр огцом буурах ба гадаад хэлхээнээс хэмжигдэх <b>илэрхий цэнэг</b> (apparent charge) нь"}, {"t": "eq", "s": "q a≈C b ΔU c (10.12)", "h": "q<sub>a</sub>≈C<sub>b</sub> ΔU<sub>c</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q</mi><mi>a</mi></msub><mo>≈</mo><msub><mi>C</mi><mi>b</mi></msub><mspace width=\"0.167em\"></mspace><mi>Δ</mi><msub><mi>U</mi><mi>c</mi></msub></mrow></semantics></math>", "n": "10.12"}, {"t": "p", "s": "болно (C a≫C b үед). Хөндий дэх бодит цэнэг q c≈(C b+C c)ΔU c нь илэрхий цэнэгээс хэд дахин их бөгөөд гаднаас хэмжих боломжгүй. Иймээс стандартад PD-ийн хэмжээг илэрхий цэнэгээр (пКл) илэрхийлнэ.", "h": "болно (C<sub>a</sub>≫C<sub>b</sub> үед). Хөндий дэх бодит цэнэг q<sub>c</sub>≈(C<sub>b</sub>+C<sub>c</sub>)ΔU<sub>c</sub> нь илэрхий цэнэгээс хэд дахин их бөгөөд гаднаас хэмжих боломжгүй. Иймээс стандартад PD-ийн хэмжээг илэрхий цэнэгээр (пКл) илэрхийлнэ."}, {"t": "h", "l": 2, "s": "3.2. Хэмжих аргууд", "h": "3.2. Хэмжих аргууд"}, {"t": "p", "s": "IEC 60270 (цахилгаан, уламжлалт арга). Туршилтын объекттой зэрэгцээ холбосон холбох конденсатор C k ба хэмжих импеданс (quadripole)-аар PD-ийн гүйдлийн импульсийг бүртгэж, 100–500 кГц-ийн зурваст интегралчилан цэнэгийг тодорхойлно. Хэмжилтийн өмнө объектын терминалд мэдэгдэж буй цэнэг q cal шахах калибратороор хэмжих системийн масштабыг тогтооно:", "h": "<b>IEC 60270 (цахилгаан, уламжлалт арга).</b> Туршилтын объекттой зэрэгцээ холбосон холбох конденсатор C<sub>k</sub> ба хэмжих импеданс (quadripole)-аар PD-ийн гүйдлийн импульсийг бүртгэж, 100–500 кГц-ийн зурваст интегралчилан цэнэгийг тодорхойлно. Хэмжилтийн өмнө объектын терминалд мэдэгдэж буй цэнэг q<sub>cal</sub> шахах калибратороор хэмжих системийн масштабыг тогтооно:"}, {"t": "eq", "s": "q=q cal U m/(U cal) (10.13)", "h": "q=q<sub>cal</sub> U<sub>m</sub>/(U<sub>cal</sub>)", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q</mi><mo>=</mo><msub><mi>q</mi><mrow><mi>c</mi><mi>a</mi><mi>l</mi></mrow></msub><mspace width=\"0.167em\"></mspace><mfrac><msub><mi>U</mi><mi>m</mi></msub><msub><mi>U</mi><mrow><mi>c</mi><mi>a</mi><mi>l</mi></mrow></msub></mfrac></mrow></semantics></math>", "n": "10.13"}, {"t": "p", "s": "энд U cal — калибрлалтын импульсийн хариу, U m — PD-ийн импульсийн хариу. IEC 60270 нь үйлдвэрийн хүлээн авах туршилтын суурь арга боловч дэд станцын шуугиантай орчинд онлайн хэрэглэхэд хүндрэлтэй.", "h": "энд U<sub>cal</sub> — калибрлалтын импульсийн хариу, U<sub>m</sub> — PD-ийн импульсийн хариу. IEC 60270 нь үйлдвэрийн хүлээн авах туршилтын суурь арга боловч дэд станцын шуугиантай орчинд онлайн хэрэглэхэд хүндрэлтэй."}, {"t": "p", "s": "UHF арга (0.3–3 ГГц). PD-ийн наносекундын импульс цахилгаан соронзон долгион болж тархах ба металл бүрхүүл гадаад шуугианаас хамгаалах тул GIS-д UHF арга онлайн хяналтын үндсэн хэрэгсэл болсон (Зураг 10.7). Дотоод дискэн мэдрэгчийг үйлдвэрээс суурилуулах, эсвэл тулгуур тусгаарлагчийн цонх, хавхлагаар гадаад мэдрэгч хэрэглэнэ. Сул тал: пКл-оор шууд калибрлах боломжгүй (CIGRE-ийн «мэдрэмжийн шалгалт»-аар 5 пКл-ийн тэнцүү эх үүсвэрийг илрүүлэх чадварыг баталгаажуулдаг).", "h": "<b>UHF арга (0.3–3 ГГц).</b> PD-ийн наносекундын импульс цахилгаан соронзон долгион болж тархах ба металл бүрхүүл гадаад шуугианаас хамгаалах тул GIS-д UHF арга онлайн хяналтын үндсэн хэрэгсэл болсон (Зураг 10.7). Дотоод дискэн мэдрэгчийг үйлдвэрээс суурилуулах, эсвэл тулгуур тусгаарлагчийн цонх, хавхлагаар гадаад мэдрэгч хэрэглэнэ. Сул тал: пКл-оор шууд калибрлах боломжгүй (CIGRE-ийн «мэдрэмжийн шалгалт»-аар 5 пКл-ийн тэнцүү эх үүсвэрийг илрүүлэх чадварыг баталгаажуулдаг)."}, {"t": "p", "s": "Акустик арга (20–300 кГц). Савны хананд пьезо мэдрэгч наан PD-ийн механик долгионыг бүртгэнэ. Олон мэдрэгчийн долгион ирэх хугацааны зөрүүгээр гэмтлийн байрлалыг дециметрийн нарийвчлалтай тогтоох боломжтой; тосонд дууны хурд ≈ 1400 м/с. IEC TS 62478 нь цахилгаан соронзон ба акустик аргыг зохицуулна.", "h": "<b>Акустик арга (20–300 кГц).</b> Савны хананд пьезо мэдрэгч наан PD-ийн механик долгионыг бүртгэнэ. Олон мэдрэгчийн долгион ирэх хугацааны зөрүүгээр гэмтлийн байрлалыг дециметрийн нарийвчлалтай тогтоох боломжтой; тосонд дууны хурд ≈ 1400 м/с. IEC TS 62478 нь цахилгаан соронзон ба акустик аргыг зохицуулна."}, {"t": "p", "s": "HFCT (өндөр давтамжийн гүйдлийн трансформатор) мэдрэгчийг кабелийн бүрхүүл, газардуулгын утсанд хавчуулж (Лекц 7), TEV (түр зуурын газрын хүчдэл) мэдрэгчээр 6–35 кВ-ын КРУ-ийн металл бүрхүүлийн гадаргуугийн импульсийг гаднаас хэмжинэ.", "h": "<b>HFCT</b> (өндөр давтамжийн гүйдлийн трансформатор) мэдрэгчийг кабелийн бүрхүүл, газардуулгын утсанд хавчуулж (Лекц 7), <b>TEV</b> (түр зуурын газрын хүчдэл) мэдрэгчээр 6–35 кВ-ын КРУ-ийн металл бүрхүүлийн гадаргуугийн импульсийг гаднаас хэмжинэ."}, {"t": "cap", "s": "Хүснэгт 10.5. Хэсэгчилсэн цэнэг хэмжих аргуудын харьцуулалт", "h": "Хүснэгт 10.5. Хэсэгчилсэн цэнэг хэмжих аргуудын харьцуулалт"}, {"t": "tbl", "s": "", "head": ["Арга", "Давтамж", "Хэрэглээ", "Давуу тал", "Сул тал"], "rows": [["IEC 60270", "0.1–0.5 МГц", "Үйлдвэрийн туршилт, офлайн", "пКл-оор калибрлагдана", "Шуугианд мэдрэг, холбох конденсатор"], ["UHF", "0.3–3 ГГц", "GIS, трансформатор", "Шуугианаас хамгаалалттай, байршил", "Калибрлалт шууд биш"], ["Акустик", "20–300 кГц", "Трансформатор, GIS (бөөм)", "Байрлал тогтоох, цахилгаан шуугиангүй", "Сулрал их, гүнд мэдрэмж бага"], ["HFCT", "0.1–30 МГц", "Кабель, газардуулгын утас", "Суурилуулахад хялбар", "Гадаад шуугиан"], ["TEV", "3–100 МГц", "6–35 кВ КРУ", "Хямд, хурдан шалгалт", "Чанарын төдий үнэлгээ"]]}, {"t": "h", "l": 2, "s": "3.3. PRPD дүрс", "h": "3.3. PRPD дүрс"}, {"t": "p", "s": "Хэсэгчилсэн цэнэгийг тэжээлийн хүчдэлийн фазтай уялдуулан бүртгэсэн PRPD (phase-resolved partial discharge) дүрс нь гэмтлийн төрлийг таних гол хэрэгсэл юм (Зураг 10.6):", "h": "Хэсэгчилсэн цэнэгийг тэжээлийн хүчдэлийн фазтай уялдуулан бүртгэсэн <b>PRPD</b> (phase-resolved partial discharge) дүрс нь гэмтлийн төрлийг таних гол хэрэгсэл юм (Зураг 10.6):"}, {"t": "p", "s": "Дотоод хөндий — эерэг ба сөрөг хагас үед ойролцоогоор тэгш хэмтэй, хүчдэл өсөх хэсэгт (0–90° ба 180–270°) төвлөрсөн «туулайн чих» хэлбэр;", "h": "• <b>Дотоод хөндий</b> — эерэг ба сөрөг хагас үед ойролцоогоор тэгш хэмтэй, хүчдэл өсөх хэсэгт (0–90° ба 180–270°) төвлөрсөн «туулайн чих» хэлбэр;"}, {"t": "p", "s": "Гадаргын цэнэг — тэгш бус, нэг туйлд хэмжээ илүү их;", "h": "• <b>Гадаргын цэнэг</b> — тэгш бус, нэг туйлд хэмжээ илүү их;"}, {"t": "p", "s": "Титэм (корона) — өндөр хүчдэлтэй хурц үзүүрт сөрөг хагас үеийн оргилын орчим ижил хэмжээний олон жижиг импульс; хүчдэл өсөхөд эерэг хагас үед ч гарч эхэлнэ;", "h": "• <b>Титэм (корона)</b> — өндөр хүчдэлтэй хурц үзүүрт сөрөг хагас үеийн оргилын орчим ижил хэмжээний олон жижиг импульс; хүчдэл өсөхөд эерэг хагас үед ч гарч эхэлнэ;"}, {"t": "p", "s": "Хөвөгч потенциал — хоёр хагас үед ижил хэмжээтэй, тогтмол фазын зайтай том импульсүүд;", "h": "• <b>Хөвөгч потенциал</b> — хоёр хагас үед ижил хэмжээтэй, тогтмол фазын зайтай том импульсүүд;"}, {"t": "p", "s": "GIS дахь чөлөөт бөөм — фазаас бараг хамааралгүй, хэмжээ нь санамсаргүй, акустикаар «цохилт» хэлбэрээр сонсогдоно.", "h": "• <b>GIS дахь чөлөөт бөөм</b> — фазаас бараг хамааралгүй, хэмжээ нь санамсаргүй, акустикаар «цохилт» хэлбэрээр сонсогдоно."}, {"t": "p", "s": "Орчин үеийн системүүд PRPD-г машин сургалтын аргаар автоматаар ангилдаг.", "h": "Орчин үеийн системүүд PRPD-г машин сургалтын аргаар автоматаар ангилдаг."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.6. PRPD дүрсийн жишээ (загварчилсан)", "h": "Зураг 10.6. PRPD дүрсийн жишээ (загварчилсан)"}, {"t": "h", "l": 2, "s": "3.4. КРУЭ/GIS-д\nхэсэгчилсэн цэнэгийн байрлал тогтоох", "h": "3.4. КРУЭ/GIS-д\nхэсэгчилсэн цэнэгийн байрлал тогтоох"}, {"t": "p", "s": "GIS-ийн хоёр UHF мэдрэгчийн хооронд (L зайтай) PD үүсвэл, импульс мэдрэгч бүрд ирэх хугацааны зөрүүгээр байрлалыг тодорхойлно (Зураг 10.7):", "h": "GIS-ийн хоёр UHF мэдрэгчийн хооронд (L зайтай) PD үүсвэл, импульс мэдрэгч бүрд ирэх хугацааны зөрүүгээр байрлалыг тодорхойлно (Зураг 10.7):"}, {"t": "eq", "s": "x A=(L−c (t B−t A))/2 (10.14)", "h": "x<sub>A</sub>=(L−c (t<sub>B</sub>−t<sub>A</sub>))/2", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x</mi><mi>A</mi></msub><mo>=</mo><mfrac><mrow><mi>L</mi><mo>−</mo><mi>c</mi><mspace width=\"0.167em\"></mspace><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><msub><mi>t</mi><mi>B</mi></msub><mo>−</mo><msub><mi>t</mi><mi>A</mi></msub><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow><mn>2</mn></mfrac></mrow></semantics></math>", "n": "10.14"}, {"t": "p", "s": "энд x A — A мэдрэгчээс гэмтэл хүртэлх зай, м; c≈0.3 м/нс — цахилгаан соронзон долгионы хурд; t A, t B — импульсийн ирэх хугацаа. Хугацааг 1 нс-ийн нарийвчлалтай хэмжвэл байрлал ±15 см-ийн нарийвчлалтай тогтоно. GIS-ийн PD-ийн гол эх үүсвэр нь угсралтын үеэр үлдсэн металл бөөм, тулгуур тусгаарлагчийн гадаргын бохирдол, сул холбоос, хурц ирмэг юм. Иймээс шинэ GIS-ийг ашиглалтад оруулах туршилтын үед UHF хэмжилт хийх нь чухал (Лекц 2).", "h": "энд x<sub>A</sub> — A мэдрэгчээс гэмтэл хүртэлх зай, м; c≈0.3 м/нс — цахилгаан соронзон долгионы хурд; t<sub>A</sub>, t<sub>B</sub> — импульсийн ирэх хугацаа. Хугацааг 1 нс-ийн нарийвчлалтай хэмжвэл байрлал ±15 см-ийн нарийвчлалтай тогтоно. GIS-ийн PD-ийн гол эх үүсвэр нь угсралтын үеэр үлдсэн металл бөөм, тулгуур тусгаарлагчийн гадаргын бохирдол, сул холбоос, хурц ирмэг юм. Иймээс шинэ GIS-ийг ашиглалтад оруулах туршилтын үед UHF хэмжилт хийх нь чухал (Лекц 2)."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.7. КРУЭ/GIS-ийн UHF мэдрэгч ба хэсэгчилсэн цэнэгийн байрлал тогтоох схем", "h": "Зураг 10.7. КРУЭ/GIS-ийн UHF мэдрэгч ба хэсэгчилсэн цэнэгийн байрлал тогтоох схем"}, {"t": "p", "s": "Жишээ 10.6. (а) IEC 60270-ийн хэмжилтэд 100 пКл калибраторын хариу 52 мВ, PD-ийн импульсийн хариу 180 мВ байв. Илэрхий цэнэгийг тодорхойл. (б) 220 кВ-ын GIS-ийн хоорондоо 6 м зайтай A ба B UHF мэдрэгчид импульс B-д A-аас 8 нс хойно иржээ. Гэмтлийн байрлалыг ол. (в) Трансформаторын савны акустик мэдрэгч цахилгаан (UHF) дохионоос 0.85 мс хоцорч дохио авсан бол гэмтэл мэдрэгчээс хэр зайд вэ?", "h": "<b>Жишээ 10.6.</b> (а) IEC 60270-ийн хэмжилтэд 100 пКл калибраторын хариу 52 мВ, PD-ийн импульсийн хариу 180 мВ байв. Илэрхий цэнэгийг тодорхойл. (б) 220 кВ-ын GIS-ийн хоорондоо 6 м зайтай A ба B UHF мэдрэгчид импульс B-д A-аас 8 нс хойно иржээ. Гэмтлийн байрлалыг ол. (в) Трансформаторын савны акустик мэдрэгч цахилгаан (UHF) дохионоос 0.85 мс хоцорч дохио авсан бол гэмтэл мэдрэгчээс хэр зайд вэ?", "x": "ex"}, {"t": "p", "s": "Бодолт. (а) (10.13)-аар q=100⋅180/52=346 пКл.", "h": "<i>Бодолт.</i> (а) (10.13)-аар q=100⋅180/52=346 пКл.", "x": "ex"}, {"t": "p", "s": "(б) (10.14)-өөр x A=(6−0.3⋅8)/2=(6−2.4)/2=1.8 м — A мэдрэгчээс 1.8 м, B-ээс 4.2 м зайд. Шалгалт: 4.2−1.8=2.4 м = 0.3⋅8 м.", "h": "(б) (10.14)-өөр x<sub>A</sub>=(6−0.3⋅8)/2=(6−2.4)/2=1.8 м — A мэдрэгчээс 1.8 м, B-ээс 4.2 м зайд. Шалгалт: 4.2−1.8=2.4 м = 0.3⋅8 м.", "x": "ex"}, {"t": "p", "s": "(в) Цахилгаан соронзон дохио бараг агшин зуур ирэх тул хоцрогдол нь акустик долгионы тархалтын хугацаа: d=1400⋅0.85⋅10^−3=1.19 м. Гурав ба түүнээс дээш мэдрэгчээр гэмтлийн цэгийг бөмбөрцгүүдийн огтлолцлоор олно.", "h": "(в) Цахилгаан соронзон дохио бараг агшин зуур ирэх тул хоцрогдол нь акустик долгионы тархалтын хугацаа: d=1400⋅0.85⋅10<sup>−3</sup>=1.19 м. Гурав ба түүнээс дээш мэдрэгчээр гэмтлийн цэгийг бөмбөрцгүүдийн огтлолцлоор олно.", "x": "ex"}, {"t": "h", "l": 1, "s": "4. Хуваарилах\nбайгууламжийн тоноглолын хяналт", "h": "4. Хуваарилах\nбайгууламжийн тоноглолын хяналт"}, {"t": "h", "l": 2, "s": "4.1. КРУЭ/GIS-ийн SF6 нягтын\nхяналт", "h": "4.1. КРУЭ/GIS-ийн SF6 нягтын\nхяналт"}, {"t": "p", "s": "GIS-ийн тусгаарлага ба таслуурын нум унтраах чадвар SF6 хийн нягтаас хамаардаг. Битүү тасалгаанд хийн масс тогтмол бол температур өөрчлөгдөхөд даралт өөрчлөгдөх ч нягт өөрчлөгдөхгүй. Иймээс даралтыг 20 °C-д шилжүүлж харьцуулна (идеал хийн ойролцоо):", "h": "GIS-ийн тусгаарлага ба таслуурын нум унтраах чадвар SF6 хийн <b>нягт</b>аас хамаардаг. Битүү тасалгаанд хийн масс тогтмол бол температур өөрчлөгдөхөд даралт өөрчлөгдөх ч нягт өөрчлөгдөхгүй. Иймээс даралтыг 20 °C-д шилжүүлж харьцуулна (идеал хийн ойролцоо):"}, {"t": "eq", "s": "p 20=p T (293.15)/T (10.15)", "h": "p<sub>20</sub>=p<sub>T</sub> (293.15)/T", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mn>20</mn></msub><mo>=</mo><msub><mi>p</mi><mi>T</mi></msub><mspace width=\"0.167em\"></mspace><mfrac><mn>293.15</mn><mi>T</mi></mfrac></mrow></semantics></math>", "n": "10.15"}, {"t": "p", "s": "энд p T — T (К) температурт хэмжсэн үнэмлэхүй даралт. Уламжлалт нягтын реле нь температурын нөхөлттэй механик багаж бөгөөд дохиоллын (жишээ нь нэрлэсэн утгаас 10 % буурах) ба түгжээний (ажиллагааг хориглох) хоёр шаттай. Онлайн дижитал нягтын мэдрэгч нь даралт, температурыг тасралтгүй хэмжиж, IEC 61850-аар дамжуулан нягтын чиг хандлага, алдагдлын хурд, дохиолол хүртэлх хугацааг тооцоолох боломж олгоно. Жилийн харьцангуй алдагдлын хурд", "h": "энд p<sub>T</sub> — T (К) температурт хэмжсэн үнэмлэхүй даралт. Уламжлалт нягтын реле нь температурын нөхөлттэй механик багаж бөгөөд дохиоллын (жишээ нь нэрлэсэн утгаас 10 % буурах) ба түгжээний (ажиллагааг хориглох) хоёр шаттай. Онлайн дижитал нягтын мэдрэгч нь даралт, температурыг тасралтгүй хэмжиж, IEC 61850-аар дамжуулан <b>нягтын чиг хандлага</b>, алдагдлын хурд, дохиолол хүртэлх хугацааг тооцоолох боломж олгоно. Жилийн харьцангуй алдагдлын хурд"}, {"t": "eq", "s": "F=Δρ/(ρ 0 Δt)⋅100 % (10.16)", "h": "F=Δρ/(ρ<sub>0</sub> Δt)⋅100 %", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi><mo>=</mo><mfrac><mrow><mi>Δ</mi><mi>ρ</mi></mrow><mrow><msub><mi>ρ</mi><mn>0</mn></msub><mspace width=\"0.167em\"></mspace><mi>Δ</mi><mi>t</mi></mrow></mfrac><mo>⋅</mo><mn>100</mn><mspace width=\"0.167em\"></mspace><mi>%</mi></mrow></semantics></math>", "n": "10.16"}, {"t": "p", "s": "IEC 62271-203-аар тасалгаа бүрийн алдагдал жилд 0.5 %-иас хэтрэхгүй байх ёстой. Монголд −40 °C-д SF6 хэсэгчлэн шингэрэх, өдөр шөнийн 30–35 К-ийн хэлбэлзэл манометрийг төөрөгдүүлэх тул SF6/N₂ холимог, халаалт эсвэл SF6-гүй технологи (Лекц 2, 3) сонгодог.", "h": "IEC 62271-203-аар тасалгаа бүрийн алдагдал жилд 0.5 %-иас хэтрэхгүй байх ёстой. Монголд −40 °C-д SF6 хэсэгчлэн шингэрэх, өдөр шөнийн 30–35 К-ийн хэлбэлзэл манометрийг төөрөгдүүлэх тул SF6/N₂ холимог, халаалт эсвэл SF6-гүй технологи (Лекц 2, 3) сонгодог."}, {"t": "p", "s": "Жишээ 10.7. 110 кВ-ын GIS-ийн таслуурын тасалгаа: нэрлэсэн нягт 20 °C-д 0.60 МПа (үнэмлэхүй), дохиолол 0.52 МПа, түгжээ 0.50 МПа, SF6-ийн масс 35 кг. Онлайн мэдрэгч 6 сарын хугацаанд 20 °C-д шилжүүлсэн даралт 0.006 МПа-аар буурсныг үзүүлэв. (а) Алдагдлын хурд, (б) дохиолол хүртэлх хугацаа, (в) жилийн хүлэмжийн хийн ялгаруулалт; (г) нөхөлтгүй манометр −30 °C-д юу заахыг тооцъё.", "h": "<b>Жишээ 10.7.</b> 110 кВ-ын GIS-ийн таслуурын тасалгаа: нэрлэсэн нягт 20 °C-д 0.60 МПа (үнэмлэхүй), дохиолол 0.52 МПа, түгжээ 0.50 МПа, SF6-ийн масс 35 кг. Онлайн мэдрэгч 6 сарын хугацаанд 20 °C-д шилжүүлсэн даралт 0.006 МПа-аар буурсныг үзүүлэв. (а) Алдагдлын хурд, (б) дохиолол хүртэлх хугацаа, (в) жилийн хүлэмжийн хийн ялгаруулалт; (г) нөхөлтгүй манометр −30 °C-д юу заахыг тооцъё.", "x": "ex"}, {"t": "p", "s": "Бодолт. (а) (10.16)-аар F=0.006/(0.60⋅0.5)⋅100=2.0 %/жил — стандартын 0.5 %-иас 4 дахин их тул алдагдлын байрлалыг (хийн камер, лазер «нүдээр харах» арга) тогтоож засна.", "h": "<i>Бодолт.</i> (а) (10.16)-аар F=0.006/(0.60⋅0.5)⋅100=2.0 %/жил — стандартын 0.5 %-иас 4 дахин их тул алдагдлын байрлалыг (хийн камер, лазер «нүдээр харах» арга) тогтоож засна.", "x": "ex"}, {"t": "p", "s": "(б) Дохиолол хүртэл (0.60−0.52)/0.012=6.7 жил. Онлайн чиг хандлагаар засварыг яаралтай бус, төлөвлөгөөт хугацаанд хийх боломжтой болж байна — CBM-ийн давуу тал.", "h": "(б) Дохиолол хүртэл (0.60−0.52)/0.012=6.7 жил. Онлайн чиг хандлагаар засварыг яаралтай бус, төлөвлөгөөт хугацаанд хийх боломжтой болж байна — CBM-ийн давуу тал.", "x": "ex"}, {"t": "p", "s": "(в) Жилд 35⋅0.02=0.70 кг SF6, GWP≈23 500 тул 0.70⋅23 500=16.5 т CO₂-эквивалент; стандартын 0.5 %-ийн үед 4.1 т байх байсан.", "h": "(в) Жилд 35⋅0.02=0.70 кг SF6, GWP≈23 500 тул 0.70⋅23 500=16.5 т CO₂-эквивалент; стандартын 0.5 %-ийн үед 4.1 т байх байсан.", "x": "ex"}, {"t": "p", "s": "(г) (10.15)-аас p T=0.60⋅243.15/293.15=0.498 МПа. Нягт өөрчлөгдөөгүй ч нөхөлтгүй манометр дохиоллын түвшнээс бага утга заана. Иймээс зөвхөн температурын нөхөлттэй нягтын мэдрэгчийн утгаар шийдвэр гаргана.", "h": "(г) (10.15)-аас p<sub>T</sub>=0.60⋅243.15/293.15=0.498 МПа. Нягт өөрчлөгдөөгүй ч нөхөлтгүй манометр дохиоллын түвшнээс бага утга заана. Иймээс зөвхөн температурын нөхөлттэй нягтын мэдрэгчийн утгаар шийдвэр гаргана.", "x": "ex"}, {"t": "h", "l": 2, "s": "4.2. Таслуурын хяналт", "h": "4.2. Таслуурын хяналт"}, {"t": "p", "s": "Таслуурын онлайн хяналтын үндсэн параметрүүд нь:", "h": "Таслуурын онлайн хяналтын үндсэн параметрүүд нь:"}, {"t": "p", "s": "Салгах ба залгах ороомгийн гүйдлийн муруй (Зураг 10.8). Тушаал өгөхөд (T0) гүйдэл ороомгийн индукцээр өсч, зүрхэвч хөдөлж эхлэхэд (T1) хөдөлгөөний ЭХХ-ийн нөлөөгөөр гүйдэл буурна; түгжээ суллагдаж зүрхэвч зогсоход (T2) хамгийн бага цэгт хүрээд дахин өсч, ханалтад (T3) хүрнэ; туслах контакт хэлхээг таслахад (T4) гүйдэл тэг болно. Муруйн хэлбэр, оргил утга, T1–T4 хугацааг жишигтэй харьцуулж, тэжээлийн хүчдэл буурсан, зүрхэвч гацсан, тос хөлдсөн, механизм үрэлт ихэссэн, туслах контакт гэмтсэнийг илрүүлнэ.", "h": "• <b>Салгах ба залгах ороомгийн гүйдлийн муруй</b> (Зураг 10.8). Тушаал өгөхөд (T0) гүйдэл ороомгийн индукцээр өсч, зүрхэвч хөдөлж эхлэхэд (T1) хөдөлгөөний ЭХХ-ийн нөлөөгөөр гүйдэл буурна; түгжээ суллагдаж зүрхэвч зогсоход (T2) хамгийн бага цэгт хүрээд дахин өсч, ханалтад (T3) хүрнэ; туслах контакт хэлхээг таслахад (T4) гүйдэл тэг болно. Муруйн хэлбэр, оргил утга, T1–T4 хугацааг жишигтэй харьцуулж, тэжээлийн хүчдэл буурсан, зүрхэвч гацсан, тос хөлдсөн, механизм үрэлт ихэссэн, туслах контакт гэмтсэнийг илрүүлнэ."}, {"t": "p", "s": "Контактын шилжилт (travel) ба хурд — шугаман/эргэлтийн энкодероор хэмжинэ; контакт салах агшин дахь хурд нум унтраах чадварт шууд нөлөөлнө.", "h": "• <b>Контактын шилжилт (travel) ба хурд</b> — шугаман/эргэлтийн энкодероор хэмжинэ; контакт салах агшин дахь хурд нум унтраах чадварт шууд нөлөөлнө."}, {"t": "p", "s": "Ажиллах хугацаа — тушаалаас контакт салах хүртэлх хугацаа (110–220 кВ-ын SF6 таслуурт 20–40 мс), фазуудын зөрүү (≤ 3–5 мс). Удирдлагатай коммутацад (Лекц 3) температур, тэжээлийн хүчдэлийн нөлөөг онлайн хяналтаар нөхдөг.", "h": "• <b>Ажиллах хугацаа</b> — тушаалаас контакт салах хүртэлх хугацаа (110–220 кВ-ын SF6 таслуурт 20–40 мс), фазуудын зөрүү (≤ 3–5 мс). Удирдлагатай коммутацад (Лекц 3) температур, тэжээлийн хүчдэлийн нөлөөг онлайн хяналтаар нөхдөг."}, {"t": "p", "s": "Хөтлүүрийн төлөв — пүршийг цэнэглэх хөдөлгүүрийн хугацаа, гидравлик хөтлүүрийн насосны ажиллах давтамж, даралт.", "h": "• <b>Хөтлүүрийн төлөв</b> — пүршийг цэнэглэх хөдөлгүүрийн хугацаа, гидравлик хөтлүүрийн насосны ажиллах давтамж, даралт."}, {"t": "p", "s": "Контактын элэгдэл — тасалсан гүйдлийн квадрат ба нумын хугацааны үржвэрийн нийлбэр:", "h": "• <b>Контактын элэгдэл</b> — тасалсан гүйдлийн квадрат ба нумын хугацааны үржвэрийн нийлбэр:"}, {"t": "eq", "s": "W=∑ kI k^2 t нум,k (10.17)", "h": "W=∑<sub>k</sub>I<sub>k</sub><sup>2</sup> t<sub>нум,k</sub>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>W</mi><mo>=</mo><munder><mo>∑</mo><mi>k</mi></munder><msubsup><mi>I</mi><mi>k</mi><mn>2</mn></msubsup><mspace width=\"0.167em\"></mspace><msub><mi>t</mi><mrow><mi>н</mi><mi>у</mi><mi>м</mi><mo>,</mo><mi>k</mi></mrow></msub></mrow></semantics></math>", "n": "10.17"}, {"t": "p", "s": "энд I k — k-р таслалтын гүйдэл (үйлчлэх утга), кА; t нум,k — нумын хугацаа, с. Үйлдвэрлэгч зөвшөөрөгдөх нийт элэгдлийг (жишээ нь нэрлэсэн таслах гүйдлээр тодорхой тооны таслалт) өгдөг. Жишээ нь 31.5 кА-ийн таслуурт нэрлэсэн гүйдлээр 20 удаа 12 мс-ийн нумтай таслах нөөц W зөвш=20⋅31.5^2⋅0.012=238 кА²·с байг. Ашиглалтын хугацаанд 18 кА-ийн 3 ТЗ (10 мс), 25 кА-ийн 1 ТЗ (14 мс), 0.6 кА-ийн 450 ачааллын таслалт (8 мс) хийсэн бол W=3⋅18^2⋅0.010+25^2⋅0.014+450⋅0.6^2⋅0.008=9.72+8.75+1.30=19.8 кА²·с, нөөцийн 8.3 %. Цөөн ТЗ-ийн таслалт олон зуун ачааллын таслалтаас илүү элэгдэл үүсгэдэг тул засварыг бодит элэгдлээр төлөвлөнө.", "h": "энд I<sub>k</sub> — k-р таслалтын гүйдэл (үйлчлэх утга), кА; t<sub>нум,k</sub> — нумын хугацаа, с. Үйлдвэрлэгч зөвшөөрөгдөх нийт элэгдлийг (жишээ нь нэрлэсэн таслах гүйдлээр тодорхой тооны таслалт) өгдөг. Жишээ нь 31.5 кА-ийн таслуурт нэрлэсэн гүйдлээр 20 удаа 12 мс-ийн нумтай таслах нөөц W<sub>зөвш</sub>=20⋅31.5<sup>2</sup>⋅0.012=238 кА²·с байг. Ашиглалтын хугацаанд 18 кА-ийн 3 ТЗ (10 мс), 25 кА-ийн 1 ТЗ (14 мс), 0.6 кА-ийн 450 ачааллын таслалт (8 мс) хийсэн бол W=3⋅18<sup>2</sup>⋅0.010+25<sup>2</sup>⋅0.014+450⋅0.6<sup>2</sup>⋅0.008=9.72+8.75+1.30=19.8 кА²·с, нөөцийн 8.3 %. Цөөн ТЗ-ийн таслалт олон зуун ачааллын таслалтаас илүү элэгдэл үүсгэдэг тул засварыг бодит элэгдлээр төлөвлөнө."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.8. Таслуурын салгах ороомгийн гүйдэл ба контактын шилжилтийн муруй", "h": "Зураг 10.8. Таслуурын салгах ороомгийн гүйдэл ба контактын шилжилтийн муруй"}, {"t": "h", "l": 2, "s": "4.3. Хэт хүчдэл\nхязгаарлагчийн алдагдлын гүйдэл", "h": "4.3. Хэт хүчдэл\nхязгаарлагчийн алдагдлын гүйдэл"}, {"t": "p", "s": "Металл ислийн (ZnO) хэт хүчдэл хязгаарлагчаар (Лекц 11) ажлын хүчдэлд 0.5–3 мА-ийн алдагдлын гүйдэл гүйнэ. Түүний дийлэнх нь багтаамжийн байгуулагч бөгөөд варисторын төлөвийг илэрхийлэх идэвхтэй байгуулагч нь нийт гүйдлийн 10–20 % (хэдэн арваас хэдэн зуун мкА) л байдаг. Варистор хөгшрөх, чийг орох, хэт ачаалагдах үед идэвхтэй гүйдэл өсч, дулааны тогтворгүй байдал (thermal runaway) үүсч болно. Нийт гүйдлийг хэмжих энгийн миллиамперметр нь багтаамжийн гүйдэлд «живсэн» идэвхтэй гүйдлийн өөрчлөлтийг бараг мэдрэхгүй.", "h": "Металл ислийн (ZnO) хэт хүчдэл хязгаарлагчаар (Лекц 11) ажлын хүчдэлд 0.5–3 мА-ийн алдагдлын гүйдэл гүйнэ. Түүний дийлэнх нь <b>багтаамжийн</b> байгуулагч бөгөөд варисторын төлөвийг илэрхийлэх <b>идэвхтэй</b> байгуулагч нь нийт гүйдлийн 10–20 % (хэдэн арваас хэдэн зуун мкА) л байдаг. Варистор хөгшрөх, чийг орох, хэт ачаалагдах үед идэвхтэй гүйдэл өсч, дулааны тогтворгүй байдал (thermal runaway) үүсч болно. Нийт гүйдлийг хэмжих энгийн миллиамперметр нь багтаамжийн гүйдэлд «живсэн» идэвхтэй гүйдлийн өөрчлөлтийг бараг мэдрэхгүй."}, {"t": "p", "s": "IEC 60099-5-д заасан гуравдугаар гармоникийн арга: ZnO-ийн вольт-амперийн шинж огцом шугаман бус тул синусоид хүчдэлд идэвхтэй гүйдэл гармоник агуулна, харин багтаамжийн гүйдэл синусоид хэвээр. Иймээс гүйдлийн 3-р гармоник I 3r нь идэвхтэй гүйдлийн шууд үзүүлэлт болно. I 3r анхны утгаасаа хоёр дахин өсвөл нэмэлт шалгалт хийж, цааш өсвөл солино. Сүлжээний хүчдэлд 3-р гармоник байвал алдаа гардаг тул хүчдэлийн дохиогоор нөхнө. Шороон шуурганы бохирдолтой бүрхүүлийн гадаргын гүйдлийг хамгаалалтын цагиргаар тусад нь шилжүүлнэ.", "h": "IEC 60099-5-д заасан <b>гуравдугаар гармоникийн арга</b>: ZnO-ийн вольт-амперийн шинж огцом шугаман бус тул синусоид хүчдэлд идэвхтэй гүйдэл гармоник агуулна, харин багтаамжийн гүйдэл синусоид хэвээр. Иймээс гүйдлийн 3-р гармоник I<sub>3r</sub> нь идэвхтэй гүйдлийн шууд үзүүлэлт болно. I<sub>3r</sub> анхны утгаасаа хоёр дахин өсвөл нэмэлт шалгалт хийж, цааш өсвөл солино. Сүлжээний хүчдэлд 3-р гармоник байвал алдаа гардаг тул хүчдэлийн дохиогоор нөхнө. Шороон шуурганы бохирдолтой бүрхүүлийн гадаргын гүйдлийг хамгаалалтын цагиргаар тусад нь шилжүүлнэ."}, {"t": "h", "l": 2, "s": "4.4. Инфра улаан термографи", "h": "4.4. Инфра улаан термографи"}, {"t": "p", "s": "Инфра улаан камер нь объектын гадаргаас цацрах хэт улаан туяагаар (8–14 мкм) температурын зургийг гаргана. Термографи нь холболт, контакт, салгуурын хавчаар, шинын холбоос, кабелийн төгсгөл, хэмжих трансформатор, хэт хүчдэл хязгаарлагч, радиаторын бөглөрөл, оруулгын тосны түвшинг ажиллагаанд байгаа үед, хүрэлцэхгүйгээр шалгах хамгийн өргөн хэрэглэгддэг арга юм. Холболтын хэт халалтын хэмжээг температурын зөрүү ΔT-ээр үнэлнэ: ижил ачаалалтай, ижил төрлийн гурван фазын хооронд, эсвэл орчны агаартай харьцуулсан. Ангиллын ердийн шалгуурыг Хүснэгт 10.6-д үзүүлэв.", "h": "Инфра улаан камер нь объектын гадаргаас цацрах хэт улаан туяагаар (8–14 мкм) температурын зургийг гаргана. Термографи нь холболт, контакт, салгуурын хавчаар, шинын холбоос, кабелийн төгсгөл, хэмжих трансформатор, хэт хүчдэл хязгаарлагч, радиаторын бөглөрөл, оруулгын тосны түвшинг ажиллагаанд байгаа үед, хүрэлцэхгүйгээр шалгах хамгийн өргөн хэрэглэгддэг арга юм. Холболтын хэт халалтын хэмжээг <b>температурын зөрүү ΔT</b>-ээр үнэлнэ: ижил ачаалалтай, ижил төрлийн гурван фазын хооронд, эсвэл орчны агаартай харьцуулсан. Ангиллын ердийн шалгуурыг Хүснэгт 10.6-д үзүүлэв."}, {"t": "cap", "s": "Хүснэгт 10.6. Цахилгаан тоноглолын термографийн ΔT шалгуур (NETA MTS-ийн жишиг)", "h": "Хүснэгт 10.6. Цахилгаан тоноглолын термографийн ΔT шалгуур (NETA MTS-ийн жишиг)"}, {"t": "tbl", "s": "", "head": ["Ижил элементүүдийн зөрүү ΔT", "Орчинтой харьцуулсан ΔT", "Үнэлгээ", "Арга хэмжээ"], "rows": [["1–3 К", "1–10 К", "Боломжит доголдол", "Хянах, мэдээлэл цуглуулах"], ["4–15 К", "11–20 К", "Магадлалтай доголдол", "Боломжит хугацаанд засах"], ["—", "21–40 К", "Доголдол", "Засах хүртэл ойрхон хянах"], ["&gt; 15 К", "&gt; 40 К", "Ноцтой доголдол", "Нэн даруй засах"]]}, {"t": "p", "s": "Холболтын алдагдал гүйдлийн квадраттай пропорциональ тул бага ачаалалд хэмжсэн ΔT-г нэрлэсэн гүйдэлд шилжүүлнэ:", "h": "Холболтын алдагдал гүйдлийн квадраттай пропорциональ тул бага ачаалалд хэмжсэн ΔT-г нэрлэсэн гүйдэлд шилжүүлнэ:"}, {"t": "eq", "s": "ΔT нэр=ΔT хэм((I нэр)/(I хэм))^n (10.18)", "h": "ΔT<sub>нэр</sub>=ΔT<sub>хэм</sub>((I<sub>нэр</sub>)/(I<sub>хэм</sub>))<sup>n</sup>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Δ</mi><msub><mi>T</mi><mrow><mi>н</mi><mi>э</mi><mi>р</mi></mrow></msub><mo>=</mo><mi>Δ</mi><msub><mi>T</mi><mrow><mi>х</mi><mi>э</mi><mi>м</mi></mrow></msub><msup><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mfrac><msub><mi>I</mi><mrow><mi>н</mi><mi>э</mi><mi>р</mi></mrow></msub><msub><mi>I</mi><mrow><mi>х</mi><mi>э</mi><mi>м</mi></mrow></msub></mfrac><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow><mi>n</mi></msup></mrow></semantics></math>", "n": "10.18"}, {"t": "p", "s": "энд n=1.6–2 (конвекцын хөргөлтийг харгалзсан туршлагын илтгэгч). Жишээ нь 40 %-ийн ачааллын үед шинын холбоос хөрш фазаас 12 К халуун байв: n=2 бол ΔT нэр=12⋅(1/0.4)^2=75 К, n=1.6 бол 52 К — аль ч тохиолдолд «ноцтой» ангилал тул ачаалал өсөхөөс өмнө засна. Алдааны эх үүсвэр нь цацрах чадвар (гялгар хөнгөн цагаан ε = 0.1–0.2), нарны тусгал, салхи юм; Монголын өвлийн хүйтэн, салхи ΔT-г бууруулдгийг анхаарна.", "h": "энд n=1.6–2 (конвекцын хөргөлтийг харгалзсан туршлагын илтгэгч). Жишээ нь 40 %-ийн ачааллын үед шинын холбоос хөрш фазаас 12 К халуун байв: n=2 бол ΔT<sub>нэр</sub>=12⋅(1/0.4)<sup>2</sup>=75 К, n=1.6 бол 52 К — аль ч тохиолдолд «ноцтой» ангилал тул ачаалал өсөхөөс өмнө засна. Алдааны эх үүсвэр нь цацрах чадвар (гялгар хөнгөн цагаан ε = 0.1–0.2), нарны тусгал, салхи юм; Монголын өвлийн хүйтэн, салхи ΔT-г бууруулдгийг анхаарна."}, {"t": "h", "l": 1, "s": "5. Онлайн хяналтын архитектур", "h": "5. Онлайн хяналтын архитектур"}, {"t": "h", "l": 2, "s": "5.1. Системийн бүтэц", "h": "5.1. Системийн бүтэц"}, {"t": "p", "s": "Орчин үеийн хяналтын систем гурван түвшинтэй (Зураг 10.9):", "h": "Орчин үеийн хяналтын систем гурван түвшинтэй (Зураг 10.9):"}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.9. Дэд станцын онлайн хяналтын архитектур", "h": "Зураг 10.9. Дэд станцын онлайн хяналтын архитектур"}, {"t": "p", "s": "Процесс/бэйн түвшин — мэдрэгч ба хяналтын IED: DGA анализатор, оруулгын мэдрэгч, PD хүлээн авагч, SF6 нягтын мэдрэгч, таслуурын хяналтын төхөөрөмж, хэт хүчдэл хязгаарлагчийн гүйдлийн мэдрэгч, суурин IR камер. Энгийн хэмжилтэд утасгүй IoT мэдрэгч (LoRaWAN, NB-IoT, 5G) хэрэглэх нь кабелийн зардлыг эрс бууруулдаг.", "h": "• <b>Процесс/бэйн түвшин</b> — мэдрэгч ба хяналтын IED: DGA анализатор, оруулгын мэдрэгч, PD хүлээн авагч, SF6 нягтын мэдрэгч, таслуурын хяналтын төхөөрөмж, хэт хүчдэл хязгаарлагчийн гүйдлийн мэдрэгч, суурин IR камер. Энгийн хэмжилтэд утасгүй <b>IoT мэдрэгч</b> (LoRaWAN, NB-IoT, 5G) хэрэглэх нь кабелийн зардлыг эрс бууруулдаг."}, {"t": "p", "s": "Станцын түвшин — хяналтын сервер (өгөгдлийн сан, түүх, анхан шатны шинжилгээ), IEC 61850-ийн станцын шина, гарц (gateway), кибер хамгаалалт.", "h": "• <b>Станцын түвшин</b> — хяналтын сервер (өгөгдлийн сан, түүх, анхан шатны шинжилгээ), IEC 61850-ийн станцын шина, гарц (gateway), кибер хамгаалалт."}, {"t": "p", "s": "Төвийн түвшин — компанийн хөрөнгийн удирдлагын систем: эрүүл мэндийн индекс, эрсдэлийн тооцоо, засварын захиалгын систем (CMMS), аналитик ба хиймэл оюун, дижитал ихэр (Лекц 12).", "h": "• <b>Төвийн түвшин</b> — компанийн хөрөнгийн удирдлагын систем: эрүүл мэндийн индекс, эрсдэлийн тооцоо, засварын захиалгын систем (CMMS), аналитик ба хиймэл оюун, дижитал ихэр (Лекц 12)."}, {"t": "h", "l": 2, "s": "5.2. IEC 61850 дахь хяналтын\nзагвар", "h": "5.2. IEC 61850 дахь хяналтын\nзагвар"}, {"t": "p", "s": "IEC 61850-7-4 нь хяналтын функцэд зориулсан S бүлгийн логик зангилаа (supervision)-г тодорхойлсон: SIML — шингэн тусгаарлагын хяналт (уусмал хий H₂, C₂H₂ г.м., чийг), SIMG — хийн тусгаарлагын хяналт (SF6 нягт, даралт, температур), SARC — нумын хяналт, SPDC — хэсэгчилсэн цэнэгийн хяналт, SCBR — таслуурын хяналт (элэгдэл, ажиллах хугацаа), SOPM — хөтлүүрийн механизмын хяналт, SLTC — шилжүүлэгчийн хяналт, SPTR — хүчний трансформаторын хяналт, STMP — температурын хяналт. Мөн Z бүлэгт ZBSH — оруулгын (bushing), ZSAR — хэт хүчдэл хязгаарлагчийн загвар байна. Энэ нь өөр үйлдвэрлэгчийн мэдрэгчийг SCL-ээр нэг системд нэгтгэх боломж олгоно (Лекц 6). Өгөгдлийг MMS-ээр, яаралтай дохиоллыг GOOSE-оор дамжуулна.", "h": "IEC 61850-7-4 нь хяналтын функцэд зориулсан <b>S бүлгийн логик зангилаа</b> (supervision)-г тодорхойлсон: SIML — шингэн тусгаарлагын хяналт (уусмал хий H₂, C₂H₂ г.м., чийг), SIMG — хийн тусгаарлагын хяналт (SF6 нягт, даралт, температур), SARC — нумын хяналт, SPDC — хэсэгчилсэн цэнэгийн хяналт, SCBR — таслуурын хяналт (элэгдэл, ажиллах хугацаа), SOPM — хөтлүүрийн механизмын хяналт, SLTC — шилжүүлэгчийн хяналт, SPTR — хүчний трансформаторын хяналт, STMP — температурын хяналт. Мөн Z бүлэгт ZBSH — оруулгын (bushing), ZSAR — хэт хүчдэл хязгаарлагчийн загвар байна. Энэ нь өөр үйлдвэрлэгчийн мэдрэгчийг SCL-ээр нэг системд нэгтгэх боломж олгоно (Лекц 6). Өгөгдлийг MMS-ээр, яаралтай дохиоллыг GOOSE-оор дамжуулна."}, {"t": "p", "s": "Хяналтын гол сорилт нь өгөгдлөөс ашигтай мэдээлэл гаргах явдал тул (1) хэмжилтийг температур, ачааллаар нормчлох; (2) үнэмлэхүй хязгаараас гадна өсөлтийн хурдаар дохиолох; (3) хэд хэдэн шинж тэмдгийг хослуулах (жишээ нь DGA-ийн H₂ өсөлт + UHF PD + акустик дохио) замаар худал дохиоллыг бууруулна.", "h": "Хяналтын гол сорилт нь өгөгдлөөс <b>ашигтай мэдээлэл</b> гаргах явдал тул (1) хэмжилтийг температур, ачааллаар нормчлох; (2) үнэмлэхүй хязгаараас гадна өсөлтийн хурдаар дохиолох; (3) хэд хэдэн шинж тэмдгийг хослуулах (жишээ нь DGA-ийн H₂ өсөлт + UHF PD + акустик дохио) замаар худал дохиоллыг бууруулна."}, {"t": "h", "l": 1, "s": "6. Эрүүл мэндийн\nиндекс ба эрсдэлийн үнэлгээ", "h": "6. Эрүүл мэндийн\nиндекс ба эрсдэлийн үнэлгээ"}, {"t": "h", "l": 2, "s": "6.1. Эрүүл мэндийн индекс", "h": "6.1. Эрүүл мэндийн индекс"}, {"t": "p", "s": "Эрүүл мэндийн индекс (health index, HI) нь олон хэмжилт, шинжилгээ, ашиглалтын түүхийг нэг тоонд нэгтгэж, тоноглолын ерөнхий төлөвийг илэрхийлэх арга юм. Ердийн хэлбэр нь үзүүлэлт бүрийг 0 (маш сайн)-ээс 4 (маш муу) хүртэлх оноогоор үнэлж, жинлэсэн нийлбэрээр 0–100 хуваарьт шилжүүлэх:", "h": "<b>Эрүүл мэндийн индекс</b> (health index, HI) нь олон хэмжилт, шинжилгээ, ашиглалтын түүхийг нэг тоонд нэгтгэж, тоноглолын ерөнхий төлөвийг илэрхийлэх арга юм. Ердийн хэлбэр нь үзүүлэлт бүрийг 0 (маш сайн)-ээс 4 (маш муу) хүртэлх оноогоор үнэлж, жинлэсэн нийлбэрээр 0–100 хуваарьт шилжүүлэх:"}, {"t": "eq", "s": "HI=100(1−(∑ jw j s j)/(4∑ jw j)) (10.19)", "h": "HI=100(1−(∑<sub>j</sub>w<sub>j</sub> s<sub>j</sub>)/(4∑<sub>j</sub>w<sub>j</sub>))", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H</mi><mi>I</mi><mo>=</mo><mn>100</mn><mrow><mo form=\"prefix\" stretchy=\"true\">(</mo><mn>1</mn><mo>−</mo><mfrac><mrow><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>w</mi><mi>j</mi></msub><mspace width=\"0.167em\"></mspace><msub><mi>s</mi><mi>j</mi></msub></mrow><mrow><mn>4</mn><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>w</mi><mi>j</mi></msub></mrow></mfrac><mo form=\"postfix\" stretchy=\"true\">)</mo></mrow></mrow></semantics></math>", "n": "10.19"}, {"t": "p", "s": "энд s j — j-р үзүүлэлтийн оноо (0–4); w j — жин. HI=100 нь шинэ тоноглол, HI<30 нь амьдралын төгсгөлд ойртсоныг илтгэнэ. Жинг шинжээчийн үнэлгээ, гэмтлийн статистикаар тогтооно; CIGRE TB 761 (2019) трансформаторын төлөвийн үнэлгээний ийм аргачлалын жишээг өгсөн.", "h": "энд s<sub>j</sub> — j-р үзүүлэлтийн оноо (0–4); w<sub>j</sub> — жин. HI=100 нь шинэ тоноглол, HI&lt;30 нь амьдралын төгсгөлд ойртсоныг илтгэнэ. Жинг шинжээчийн үнэлгээ, гэмтлийн статистикаар тогтооно; CIGRE TB 761 (2019) трансформаторын төлөвийн үнэлгээний ийм аргачлалын жишээг өгсөн."}, {"t": "p", "s": "HI-г гэмтлийн магадлалтай холбохдоо паркийн гэмтлийн түүхээс тохируулсан экспоненциал хамаарлыг хэрэглэдэг:", "h": "HI-г гэмтлийн магадлалтай холбохдоо паркийн гэмтлийн түүхээс тохируулсан экспоненциал хамаарлыг хэрэглэдэг:"}, {"t": "eq", "s": "PoF=A e^−B⋅HI (10.20)", "h": "PoF=A e<sup>−B⋅HI</sup>", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P</mi><mi>o</mi><mi>F</mi><mo>=</mo><mi>A</mi><mspace width=\"0.167em\"></mspace><msup><mi>e</mi><mrow><mo>−</mo><mi>B</mi><mo>⋅</mo><mi>H</mi><mi>I</mi></mrow></msup></mrow></semantics></math>", "n": "10.20"}, {"t": "p", "s": "энд A, B — тохируулгын коэффициент. Эрсдэл нь магадлал ба үр дагаврын үржвэр:", "h": "энд A, B — тохируулгын коэффициент. Эрсдэл нь магадлал ба үр дагаврын үржвэр:"}, {"t": "eq", "s": "Risk=PoF⋅C (10.21)", "h": "Risk=PoF⋅C", "m": "<math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mi>i</mi><mi>s</mi><mi>k</mi><mo>=</mo><mi>P</mi><mi>o</mi><mi>F</mi><mo>⋅</mo><mi>C</mi></mrow></semantics></math>", "n": "10.21"}, {"t": "p", "s": "Үр дагавар C-д тасралтын хэмжээ (хэрэглэгчийн тоо, чадал, нөөц тэжээлийн боломж), аюулгүй байдал (хүн ам ойр), байгаль орчин (тос асгарах, гал), солих хугацаа ба зардал (Монголд 220 кВ-ын трансформаторыг захиалж, тээвэрлэхэд 12–18 сар) орно.", "h": "Үр дагавар C-д тасралтын хэмжээ (хэрэглэгчийн тоо, чадал, нөөц тэжээлийн боломж), аюулгүй байдал (хүн ам ойр), байгаль орчин (тос асгарах, гал), солих хугацаа ба зардал (Монголд 220 кВ-ын трансформаторыг захиалж, тээвэрлэхэд 12–18 сар) орно."}, {"t": "h", "l": 2, "s": "6.2. Эрсдэлийн матриц ба\nэрэмбэлэлт", "h": "6.2. Эрсдэлийн матриц ба\nэрэмбэлэлт"}, {"t": "p", "s": "Эрсдэлийн матриц (Зураг 10.10) нь магадлал ба үр дагаврыг хоёр тэнхлэгт байрлуулж, «ногоон» (хүлээн зөвшөөрөгдөх), «шар» (хянах), «улбар шар» (төлөвлөгөөт арга хэмжээ), «улаан» (яаралтай арга хэмжээ) бүсэд тоноглолыг ангилна. Монголын нөхцөлд эхлээд хамгийн өндөр эрсдэлтэй (220 кВ-ын, нөөцгүй) трансформаторт онлайн DGA ба оруулгын хяналт, GIS-д SF6 ба UHF хяналт суурилуулж, бусад тоноглолд зөөврийн шалгалт (термографи, TEV, офлайн DGA)-ыг хослуулах нь оновчтой.", "h": "Эрсдэлийн матриц (Зураг 10.10) нь магадлал ба үр дагаврыг хоёр тэнхлэгт байрлуулж, «ногоон» (хүлээн зөвшөөрөгдөх), «шар» (хянах), «улбар шар» (төлөвлөгөөт арга хэмжээ), «улаан» (яаралтай арга хэмжээ) бүсэд тоноглолыг ангилна. Монголын нөхцөлд эхлээд хамгийн өндөр эрсдэлтэй (220 кВ-ын, нөөцгүй) трансформаторт онлайн DGA ба оруулгын хяналт, GIS-д SF6 ба UHF хяналт суурилуулж, бусад тоноглолд зөөврийн шалгалт (термографи, TEV, офлайн DGA)-ыг хослуулах нь оновчтой."}, {"t": "fig", "s": "", "img": "data:image/png;base64,", "iw": 620}, {"t": "cap", "s": "Зураг 10.10. Эрсдэлийн матриц ба Жишээ 10.8-ын трансформаторуудын байрлал", "h": "Зураг 10.10. Эрсдэлийн матриц ба Жишээ 10.8-ын трансформаторуудын байрлал"}, {"t": "p", "s": "Жишээ 10.8. Таван трансформаторын үзүүлэлтийн оноо ба үр дагаврын зэрэг Хүснэгт 10.7-д байна. Жин: DGA w=10, тосны чанар (чийг, нэвт цохилт, хүчиллэг) w=6, цаасны төлөв (2-FAL) w=5, оруулга w=4, OLTC w=3, нас ба ачаалал w=2 (∑w=30). PoF=60 e^−0.05 HI %/жил гэж тооцож эрэмбэлье.", "h": "<b>Жишээ 10.8.</b> Таван трансформаторын үзүүлэлтийн оноо ба үр дагаврын зэрэг Хүснэгт 10.7-д байна. Жин: DGA w=10, тосны чанар (чийг, нэвт цохилт, хүчиллэг) w=6, цаасны төлөв (2-FAL) w=5, оруулга w=4, OLTC w=3, нас ба ачаалал w=2 (∑w=30). PoF=60 e<sup>−0.05 HI</sup> %/жил гэж тооцож эрэмбэлье.", "x": "ex"}, {"t": "p", "s": "Бодолт. Т1-ийн жинлэсэн нийлбэр: 10⋅2+6⋅1+5⋅2+4⋅1+3⋅1+2⋅3=49. (10.19)-өөр HI=100(1−49/120)=59.2; (10.20)-оор PoF=60e^−0.05⋅59.2=3.11 %/жил; (10.21)-ээр Risk=3.11⋅3=9.3. Бусдыг адил тооцож Хүснэгт 10.7-д үзүүлэв.", "h": "<i>Бодолт.</i> Т1-ийн жинлэсэн нийлбэр: 10⋅2+6⋅1+5⋅2+4⋅1+3⋅1+2⋅3=49. (10.19)-өөр HI=100(1−49/120)=59.2; (10.20)-оор PoF=60e<sup>−0.05⋅59.2</sup>=3.11 %/жил; (10.21)-ээр Risk=3.11⋅3=9.3. Бусдыг адил тооцож Хүснэгт 10.7-д үзүүлэв.", "x": "ex"}, {"t": "p", "s": "Т2 хамгийн муу төлөвтэй (HI=22.5) боловч үр дагавар нь бага (нөөц трансформатортой, хөдөөгийн дэд станц) тул эрсдэлээр хоёрдугаарт орно. Т4 нь дунд зэргийн төлөвтэй (HI=33.3) ч хотын төвийн олон хэрэглэгчийг тэжээдэг тул эрсдэл хамгийн их (45.3). Т3 хамгийн өндөр үр дагавартай боловч төлөв маш сайн тул эрсдэл бага. Шийдвэр: Т4-д онлайн хяналт суурилуулж солих төлөвлөгөө гаргах; Т2-ын ачааллыг хязгаарлах; Т1, Т5-д ердийн CBM. HI-ийн эрэмбэ ба эрсдэлийн эрэмбэ ялгаатай байгаа нь хөрөнгийн шийдвэрт үр дагаврыг заавал тусгах шаардлагыг харуулж байна.", "h": "Т2 хамгийн муу төлөвтэй (HI=22.5) боловч үр дагавар нь бага (нөөц трансформатортой, хөдөөгийн дэд станц) тул эрсдэлээр хоёрдугаарт орно. Т4 нь дунд зэргийн төлөвтэй (HI=33.3) ч хотын төвийн олон хэрэглэгчийг тэжээдэг тул эрсдэл хамгийн их (45.3). Т3 хамгийн өндөр үр дагавартай боловч төлөв маш сайн тул эрсдэл бага. Шийдвэр: Т4-д онлайн хяналт суурилуулж солих төлөвлөгөө гаргах; Т2-ын ачааллыг хязгаарлах; Т1, Т5-д ердийн CBM. HI-ийн эрэмбэ ба эрсдэлийн эрэмбэ ялгаатай байгаа нь хөрөнгийн шийдвэрт үр дагаврыг заавал тусгах шаардлагыг харуулж байна.", "x": "ex"}, {"t": "cap", "s": "Хүснэгт 10.7. Трансформаторын эрүүл мэндийн индекс ба эрсдэлийн эрэмбэ (Жишээ 10.8)", "h": "Хүснэгт 10.7. Трансформаторын эрүүл мэндийн индекс ба эрсдэлийн эрэмбэ (Жишээ 10.8)"}, {"t": "tbl", "s": "", "head": ["Тр-р", "DGA", "Тос", "Цаас", "Оруулга", "OLTC", "Нас", "∑ws", "HI", "PoF, %/жил", "C", "Эрсдэл", "Эрэмбэ"], "rows": [["Т1", "2", "1", "2", "1", "1", "3", "49", "59.2", "3.11", "3", "9.3", "4"], ["Т2", "4", "3", "3", "2", "2", "3", "93", "22.5", "19.5", "2", "39.0", "2"], ["Т3", "1", "1", "1", "1", "0", "1", "27", "77.5", "1.25", "5", "6.2", "5"], ["Т4", "3", "2", "3", "3", "1", "4", "80", "33.3", "11.3", "4", "45.3", "1"], ["Т5", "2", "2", "2", "1", "3", "2", "59", "50.8", "4.72", "2", "9.4", "3"]]}, {"t": "h", "l": 1, "s": "Нэр томьёо", "h": "Нэр томьёо"}, {"t": "tbl", "s": "", "head": ["Монгол", "Англи", "Орос"], "rows": [["Төлөвт суурилсан засвар", "Condition-based maintenance (CBM)", "Обслуживание по техническому состоянию"], ["Найдвартай ажиллагаанд төвлөрсөн засвар", "Reliability-centred maintenance (RCM)", "Обслуживание, ориентированное на надёжность"], ["Тосонд уусмал хийн шинжилгээ", "Dissolved gas analysis (DGA)", "Хроматографический анализ растворённых газов (ХАРГ)"], ["Полимержилтийн зэрэг", "Degree of polymerization (DP)", "Степень полимеризации"], ["Оруулга", "Bushing", "Ввод"], ["Диэлектрик алдагдлын өнцгийн тангенс", "Dissipation factor (tanδ)", "Тангенс угла диэлектрических потерь"], ["Халуун цэгийн температур", "Hot-spot temperature", "Температура наиболее нагретой точки"], ["Хэсэгчилсэн цэнэг", "Partial discharge (PD)", "Частичный разряд (ЧР)"], ["Илэрхий цэнэг", "Apparent charge", "Кажущийся заряд"], ["Ороомгийн гүйдлийн муруй", "Coil current signature", "Осциллограмма тока электромагнита"], ["Инфра улаан термографи", "Infrared thermography", "Тепловизионный контроль"], ["Эрүүл мэндийн индекс", "Health index", "Индекс технического состояния"]]}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "Дүгнэлт"}, {"t": "p", "s": "Засвар үйлчилгээ хугацаат зарчмаас төлөвт ба эрсдэлд суурилсан зарчим руу шилжиж байна; P–F интервал богино гэмтлийг зөвхөн онлайн хяналт илрүүлнэ.", "h": "• Засвар үйлчилгээ хугацаат зарчмаас төлөвт ба эрсдэлд суурилсан зарчим руу шилжиж байна; P–F интервал богино гэмтлийг зөвхөн онлайн хяналт илрүүлнэ."}, {"t": "p", "s": "DGA нь трансформаторын оношлогооны тулгуур: гэмтлийн төрлийг IEC 60599-ийн харьцаа, Дювалын гурвалжин, Рожерсийн аргаар, ноцтой байдлыг агууламж ба өсөлтийн хурдаар үнэлнэ; хэд хэдэн аргыг хослуулж дүгнэнэ.", "h": "• DGA нь трансформаторын оношлогооны тулгуур: гэмтлийн төрлийг IEC 60599-ийн харьцаа, Дювалын гурвалжин, Рожерсийн аргаар, ноцтой байдлыг агууламж ба өсөлтийн хурдаар үнэлнэ; хэд хэдэн аргыг хослуулж дүгнэнэ."}, {"t": "p", "s": "Трансформаторын ашиглалтын хугацааг халуун цэгийн температур ба чийг тодорхойлно: 6 К-ийн өсөлт хөгшрөлтийг хоёр дахин хурдасгадаг; Монголын хүйтэн өвөл ачааллын нөөц, зуны халуун эрсдэл болдог.", "h": "• Трансформаторын ашиглалтын хугацааг халуун цэгийн температур ба чийг тодорхойлно: 6 К-ийн өсөлт хөгшрөлтийг хоёр дахин хурдасгадаг; Монголын хүйтэн өвөл ачааллын нөөц, зуны халуун эрсдэл болдог."}, {"t": "p", "s": "Хэсэгчилсэн цэнэг нь тусгаарлагын эвдрэлийн эхэн үеийн шинж; GIS-д UHF, трансформаторт UHF ба акустик, кабельд HFCT, КРУ-д TEV тохиромжтой.", "h": "• Хэсэгчилсэн цэнэг нь тусгаарлагын эвдрэлийн эхэн үеийн шинж; GIS-д UHF, трансформаторт UHF ба акустик, кабельд HFCT, КРУ-д TEV тохиромжтой."}, {"t": "p", "s": "SF6 нягтын чиг хандлага, таслуурын ороомгийн гүйдэл ба I²t элэгдэл, хязгаарлагчийн 3-р гармоник гүйдэл, термографийн ΔT нь хуваарилах байгууламжийн CBM-ийн үндсэн үзүүлэлт; тэдгээрийг IEC 61850-ийн S, Z бүлгийн логик зангилаагаар нэг системд нэгтгэнэ.", "h": "• SF6 нягтын чиг хандлага, таслуурын ороомгийн гүйдэл ба I²t элэгдэл, хязгаарлагчийн 3-р гармоник гүйдэл, термографийн ΔT нь хуваарилах байгууламжийн CBM-ийн үндсэн үзүүлэлт; тэдгээрийг IEC 61850-ийн S, Z бүлгийн логик зангилаагаар нэг системд нэгтгэнэ."}, {"t": "p", "s": "Эрүүл мэндийн индекс ба эрсдэлийн матриц нь хяналтын өгөгдлийг хөрөнгө оруулалтын шийдвэр болгон хувиргана; эрэмбэлэлтэд төлөвөөс гадна үр дагаврыг заавал тусгана.", "h": "• Эрүүл мэндийн индекс ба эрсдэлийн матриц нь хяналтын өгөгдлийг хөрөнгө оруулалтын шийдвэр болгон хувиргана; эрэмбэлэлтэд төлөвөөс гадна үр дагаврыг заавал тусгана."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "Хяналтын асуулт"}, {"t": "p", "s": "Хугацаат, төлөвт суурилсан, эрсдэлд суурилсан засвар үйлчилгээг харьцуулж, P–F интервалын утгыг тайлбарла.", "h": "1. Хугацаат, төлөвт суурилсан, эрсдэлд суурилсан засвар үйлчилгээг харьцуулж, P–F интервалын утгыг тайлбарла."}, {"t": "p", "s": "Трансформаторын тосонд H₂, CH₄, C₂H₄, C₂H₂, CO үүсэх нөхцөлийг гэмтлийн энергитэй холбож тайлбарла.", "h": "2. Трансформаторын тосонд H₂, CH₄, C₂H₄, C₂H₂, CO үүсэх нөхцөлийг гэмтлийн энергитэй холбож тайлбарла."}, {"t": "p", "s": "IEC 60599-ийн харьцааны аргыг хэзээ хэрэглэх нь зүйтэй вэ? Дювалын гурвалжинд %CH₄ = 20, %C₂H₄ = 30, %C₂H₂ = 50 цэг аль бүсэд унах вэ?", "h": "3. IEC 60599-ийн харьцааны аргыг хэзээ хэрэглэх нь зүйтэй вэ? Дювалын гурвалжинд %CH₄ = 20, %C₂H₄ = 30, %C₂H₂ = 50 цэг аль бүсэд унах вэ?"}, {"t": "p", "s": "Тосны харьцангуй ханалтыг ppm-ээс юугаараа илүү гэж үздэг вэ? Хүйтэнд тос хөрөх нь ямар эрсдэл үүсгэх вэ?", "h": "4. Тосны харьцангуй ханалтыг ppm-ээс юугаараа илүү гэж үздэг вэ? Хүйтэнд тос хөрөх нь ямар эрсдэл үүсгэх вэ?"}, {"t": "p", "s": "Оруулгын C1 ба tanδ-ийн өөрчлөлт ямар гэмтлийг илтгэх вэ? Халуун цэг 98-аас 110 °C болоход хөгшрөлтийн хурд хэд дахин өсөх вэ?", "h": "5. Оруулгын C1 ба tanδ-ийн өөрчлөлт ямар гэмтлийг илтгэх вэ? Халуун цэг 98-аас 110 °C болоход хөгшрөлтийн хурд хэд дахин өсөх вэ?"}, {"t": "p", "s": "Илэрхий цэнэг ба бодит цэнэг юугаараа ялгаатай вэ? IEC 60270-д калибрлалт ямар үүрэгтэй вэ?", "h": "6. Илэрхий цэнэг ба бодит цэнэг юугаараа ялгаатай вэ? IEC 60270-д калибрлалт ямар үүрэгтэй вэ?"}, {"t": "p", "s": "GIS-д UHF аргыг яагаад голлон хэрэглэдэг вэ? Хоёр мэдрэгчээр гэмтлийн байрлалыг хэрхэн тогтоох вэ?", "h": "7. GIS-д UHF аргыг яагаад голлон хэрэглэдэг вэ? Хоёр мэдрэгчээр гэмтлийн байрлалыг хэрхэн тогтоох вэ?"}, {"t": "p", "s": "Таслуурын ороомгийн гүйдлийн муруйн T1–T4 цэгүүд юуг илэрхийлэх вэ? Ямар гэмтлийг илрүүлэх боломжтой вэ?", "h": "8. Таслуурын ороомгийн гүйдлийн муруйн T1–T4 цэгүүд юуг илэрхийлэх вэ? Ямар гэмтлийг илрүүлэх боломжтой вэ?"}, {"t": "p", "s": "Хэт хүчдэл хязгаарлагчийн нийт алдагдлын гүйдлийг хэмжих нь яагаад хангалтгүй вэ? Гуравдугаар гармоникийн аргын зарчмыг тайлбарла.", "h": "9. Хэт хүчдэл хязгаарлагчийн нийт алдагдлын гүйдлийг хэмжих нь яагаад хангалтгүй вэ? Гуравдугаар гармоникийн аргын зарчмыг тайлбарла."}, {"t": "p", "s": "Эрүүл мэндийн индекс ба эрсдэлийн эрэмбэ яагаад ялгаатай гарч болох вэ? Жишээ 10.8-аар тайлбарла.", "h": "10. Эрүүл мэндийн индекс ба эрсдэлийн эрэмбэ яагаад ялгаатай гарч болох вэ? Жишээ 10.8-аар тайлбарла."}, {"t": "h", "l": 1, "s": "Ном зүй", "h": "Ном зүй"}, {"t": "p", "s": "IEC 60599:2015. Mineral oil-filled electrical equipment in service — Guidance on the interpretation of dissolved and free gases analysis.", "h": "1. IEC 60599:2015. Mineral oil-filled electrical equipment in service — Guidance on the interpretation of dissolved and free gases analysis."}, {"t": "p", "s": "IEEE Std C57.104-2019. IEEE Guide for the Interpretation of Gases Generated in Mineral Oil-Immersed Transformers.", "h": "2. IEEE Std C57.104-2019. IEEE Guide for the Interpretation of Gases Generated in Mineral Oil-Immersed Transformers."}, {"t": "p", "s": "IEC 60076-7:2018. Power transformers — Part 7: Loading guide for mineral-oil-immersed power transformers.", "h": "3. IEC 60076-7:2018. Power transformers — Part 7: Loading guide for mineral-oil-immersed power transformers."}, {"t": "p", "s": "IEC 60270:2000+AMD1:2015. High-voltage test techniques — Partial discharge measurements.", "h": "4. IEC 60270:2000+AMD1:2015. High-voltage test techniques — Partial discharge measurements."}, {"t": "p", "s": "IEC 60422:2013. Mineral insulating oils in electrical equipment — Supervision and maintenance guidance.", "h": "5. IEC 60422:2013. Mineral insulating oils in electrical equipment — Supervision and maintenance guidance."}, {"t": "p", "s": "IEC 60099-5:2018. Surge arresters — Part 5: Selection and application recommendations.", "h": "6. IEC 60099-5:2018. Surge arresters — Part 5: Selection and application recommendations."}, {"t": "p", "s": "CIGRE TB 642. Transformer Reliability Survey. — CIGRE WG A2.37, 2015.", "h": "7. CIGRE TB 642. Transformer Reliability Survey. — CIGRE WG A2.37, 2015."}, {"t": "p", "s": "M. Duval. A review of faults detectable by gas-in-oil analysis in transformers // IEEE Electrical Insulation Magazine. — 2002. — Vol. 18, No. 3. — P. 8–17.", "h": "8. M. Duval. A review of faults detectable by gas-in-oil analysis in transformers // IEEE Electrical Insulation Magazine. — 2002. — Vol. 18, No. 3. — P. 8–17."}];